    function isLocalKiller()
        if localPlayer.Team then
            local str = localPlayer.Team.Name:lower()
            if str:find("killer") or str:find("slasher") or str:find("monster") then return true end
            if str:find("survivor") then return false end
        end

        local role = localPlayer:GetAttribute("Role")

        if role == "Killer"
            or localPlayer:GetAttribute("IsKiller") == true
            or localPlayer:GetAttribute("Killer") == true then
            return true
        end

        if role == "Survivor" then return false end
        local character = localPlayer.Character

        if character then
            local role2 = character:GetAttribute("Role")

            if role2 == "Killer"
                or character:GetAttribute("IsKiller") == true
                or character:GetAttribute("Killer") == true then
                return true
            end

            if role2 == "Survivor" then return false end
            local parent = character.Parent

            if parent and (parent.Name == "Killers" or parent.Name:lower():find("killer")) then
                return true
            end

            if parent and (parent.Name == "Survivors" or parent.Name:lower():find("survivor")) then
                return false
            end

            local collectionService = CollectionService or game:GetService("CollectionService")
            if collectionService and collectionService:HasTag(character, "Killer") then return true end
            if collectionService and collectionService:HasTag(character, "Survivor") then return false end

            if character:FindFirstChild("Firstperson")
                or character:FindFirstChild("KillerActionController")
                or character:FindFirstChild("Lookscriptkiller")
                or character:FindFirstChild("VMscript")
                or character:FindFirstChild("StunEvent")
                or character:FindFirstChild("Mori")
                or character:FindFirstChild("MoriEvent")
                or character:FindFirstChild("Killerost") then
                return true
            end

            if character:FindFirstChild("Machete")
                or character:FindFirstChild("Knife")
                or character:FindFirstChild("Weapon")
                or character:FindFirstChild("Sword")
                or character:FindFirstChild("Spear")
                or character:FindFirstChild("Hammer")
                or character:FindFirstChild("Axe")
                or character:FindFirstChild("Chainsaw")
                or character:FindFirstChild("Bat")
                or character:FindFirstChild("Attack")
                or character:FindFirstChild("AttackEvent") then
                return true
            end

            local str = character.Name:lower()

            if str:find("veil")
                or str:find("myers")
                or str:find("stalker")
                or str:find("killer")
                or str:find("abyss")
                or str:find("slasher")
                or str:find("masked")
                or str:find("jason")
                or str:find("trapper")
                or str:find("butcher")
                or str:find("hunter")
                or str:find("clown")
                or str:find("doctor")
                or str:find("phantom")
                or str:find("hidden")
                or str:find("nightmarer") then
                return true
            end
        end

        return false
    end

