    function applyPerformanceMode()
        pcall(function()
            local performanceMode = settings2.PerformanceMode or settings2.LowGraphicsMode
            local lighting2 = game:GetService("Lighting")

            if performanceMode then
                if not data and workspace.Terrain then
                    data = {
                        WaterWaveSize = workspace.Terrain.WaterWaveSize,
                        WaterWaveSpeed = workspace.Terrain.WaterWaveSpeed,
                        WaterReflectance = workspace.Terrain.WaterReflectance,
                    }
                end

                if workspace.Terrain then
                    workspace.Terrain.WaterWaveSize = 0
                    workspace.Terrain.WaterWaveSpeed = 0
                    workspace.Terrain.WaterReflectance = 0
                end

                lighting2.GlobalShadows = false

                for _, child in ipairs(lighting2:GetChildren()) do
                    if child:IsA("BlurEffect")
                        or child:IsA("SunRaysEffect")
                        or child:IsA("BloomEffect")
                        or child:IsA("DepthOfFieldEffect")
                        or child:IsA("Atmosphere") then
                        if list2[child] == nil then
                            list2[child] = child.Enabled
                        end

                        pcall(function()
                            child.Enabled = false
                        end)
                    end
                end

                pcall(function()
                    for _, descendant in ipairs(workspace:GetDescendants()) do
                        if descendant:IsA("ParticleEmitter")
                            or descendant:IsA("Smoke")
                            or descendant:IsA("Fire")
                            or descendant:IsA("Sparkles") then
                            if descendant:GetAttribute("_origRate") == nil then
                                descendant:SetAttribute("_origRate", descendant.Rate or 1)
                            end

                            descendant.Rate = 0
                        end
                    end
                end)

                pcall(function()
                    if settings and settings().Rendering then
                        settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
                    end
                end)

                pcall(function()
                    if gcinfo or collectgarbage then
                        local callback4 = collectgarbage or function() end
                        callback4("collect")
                    end
                end)
            else
                if data and workspace.Terrain then
                    workspace.Terrain.WaterWaveSize = data.WaterWaveSize or 0.15
                    workspace.Terrain.WaterWaveSpeed = data.WaterWaveSpeed or 10
                    workspace.Terrain.WaterReflectance = data.WaterReflectance or 0.05
                end

                if defaultLightingSettings then
                    lighting2.GlobalShadows = defaultLightingSettings.GlobalShadows
                end

                for k, list2Item in pairs(list2) do
                    if k and k.Parent then
                        pcall(function()
                            k.Enabled = list2Item
                        end)
                    end
                end

                list2 = {}

                pcall(function()
                    for _, descendant in ipairs(workspace:GetDescendants()) do
                        if (descendant:IsA("ParticleEmitter")
                            or descendant:IsA("Smoke")
                            or descendant:IsA("Fire")
                            or descendant:IsA("Sparkles")) and descendant:GetAttribute("_origRate") ~= nil then
                            descendant.Rate = descendant:GetAttribute("_origRate")
                            descendant:SetAttribute("_origRate", nil)
                        end
                    end
                end)

                pcall(function()
                    if settings and settings().Rendering then
                        settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic
                    end
                end)
            end
        end)
    end

