    function updateEarnedStats()
        if not hasInitializedStats then
            local screws = localPlayer:GetAttribute("Screws")
            local gears = localPlayer:GetAttribute("Gears")

            if screws and gears then
                startScrews = screws
                startGears = gears
                lastCheckedScrews = startScrews
                lastCheckedGears = startGears
                hasInitializedStats = true
            else
                return
            end
        end

        local screws = localPlayer:GetAttribute("Screws") or 0
        local gears = localPlayer:GetAttribute("Gears") or 0
        local num2 = screws - lastCheckedScrews

        if num2 > 0 then
            screwsEarnedThisSession = screwsEarnedThisSession + num2
            lifetimeScrewsEarned = lifetimeScrewsEarned + num2
        end

        lastCheckedScrews = screws
        local num3 = gears - lastCheckedGears

        if num3 > 0 then
            gearsEarnedThisSession = gearsEarnedThisSession + num3
            lifetimeGearsEarned = lifetimeGearsEarned + num3
        end

        lastCheckedGears = gears
        saveLifetimeStats()

        if updateEarnedUI then
            pcall(updateEarnedUI)
        end
    end

