    function toBase36(str)
        str = tonumber(str) or 0
        if str == 0 then return "0" end
        local str2 = "0123456789abcdefghijklmnopqrstuvwxyz"
        local str3 = ""

        while str > 0 do
            local num2 = str % 36
            str3 = str2:sub(num2 + 1, num2 + 1) .. str3
            str = math.floor(str / 36)
        end

        return str3
    end

    function fromBase36(str)
        if not str or str == "" then return "0" end
        local str2 = "0123456789abcdefghijklmnopqrstuvwxyz"
        local value = 0

        for i = 1, #str, 1 do
            local str3 = str:sub(i, i)
            local foundIndex = str2:find(str3) or 1
            value = value * 36 + (foundIndex - 1)
        end

        return tostring(value)
    end

