                            num = math.clamp(value / 1000 * 0.5, 0.015, 0.25)
                            return
                        end
                    end
                end

                local localPlayer2 = Players and Players.LocalPlayer

                if localPlayer2 then
                    local getNetworkPing = localPlayer2.GetNetworkPing

                    if type(getNetworkPing) == "function" then
                        local networkPing = getNetworkPing(localPlayer2)

                        if type(networkPing) == "number" and networkPing > 0 then
                            num = math.clamp(networkPing * 0.5, 0.015, 0.25)
                        end
                    end
                end
            end)

            task.wait(0.5)
        end
    end)

