    function serializeTable(list4, arg2)
        if type(list4) ~= "table" then return list4 end
        arg2 = arg2 or {}
        if arg2[list4] then return nil end
        arg2[list4] = true
        local map7 = {}

        for k, list4Item in pairs(list4) do
            if typeof(list4Item) == "Color3" then
                map7[k] = {
                    __type = "Color3",
                    r = math.round(list4Item.R * 255),
                    g = math.round(list4Item.G * 255),
                    b = math.round(list4Item.B * 255),
                }
            elseif type(list4Item) == "table" then
                local v2 = serializeTable(list4Item, arg2)

                if v2 ~= nil then
                    map7[k] = v2
                end
            elseif type(list4Item) == "boolean" or type(list4Item) == "number" or type(list4Item) == "string" then
                map7[k] = list4Item
            end
        end

        return map7
    end

    local function fn7(color)
        if type(color) ~= "table" then return false end
        if color.__type == "Color3" then return true end
        if (color.r or color.R) and (color.g or color.G) and (color.b or color.B) then return true end

        if #color == 3
            and type(color[1]) == "number"
            and type(color[2]) == "number"
            and type(color[3]) == "number" then
            return true
        end

        return false
    end

    local function fnFromRGB(color)
        local colorItem = color.r or color.R or color[1]
        local colorItem2 = color.g or color.G or color[2]
        local colorItem3 = color.b or color.B or color[3]
        colorItem = tonumber(colorItem) or 255
        colorItem2 = tonumber(colorItem2) or 255
        colorItem3 = tonumber(colorItem3) or 255

        if colorItem > 1 or colorItem2 > 1 or colorItem3 > 1 then
            return Color3.fromRGB(colorItem, colorItem2, colorItem3)
        else
            return Color3.new(colorItem, colorItem2, colorItem3)
        end
    end

    function deserializeTable(settings2_2, list4)
        if type(settings2_2) ~= "table" or type(list4) ~= "table" then return end

        for k, list4Item in pairs(list4) do
            if type(list4Item) == "table" then
                if fn7(list4Item) then
                    settings2_2[k] = fnFromRGB(list4Item)
                else
                    if type(settings2_2[k]) ~= "table" then
                        settings2_2[k] = {}
                    end

                    deserializeTable(settings2_2[k], list4Item)
                end
            else
                settings2_2[k] = list4Item
            end
        end
    end

