        local humanoidRootPart3 = humanoidRootPart2_2

        if not humanoidRootPart3 then
            if part:IsA("Player") then
                local character = part.Character
                humanoidRootPart3 = character and character:FindFirstChild("HumanoidRootPart")
            elseif part:IsA("Model") then
                humanoidRootPart3 = part.PrimaryPart or part:FindFirstChildWhichIsA("BasePart")
            elseif part:IsA("BasePart") then
                humanoidRootPart3 = part
