    function getGeneratorProgress(instance2)
        local repairProgress = instance2:GetAttribute("RepairProgress")

        if repairProgress == nil then
            local repairProgress2 = instance2:FindFirstChild("RepairProgress")

            if repairProgress2 and repairProgress2:IsA("ValueObject") then
                repairProgress = repairProgress2.Value
            end
        end

        if not repairProgress then return 0 end
        local num2 = tonumber(repairProgress)

        if num2 then
            if num2 <= 1.01 and num2 > 0 then
                return math.round(num2 * 100)
            else
                return math.round(num2)
            end
        end

        return 0
    end

    local object3 = setmetatable({}, {__mode = "k"})

    function isGeneratorRegressing(model)
        if not model then return false end
        local regressing = model:GetAttribute("Regressing")
        if regressing ~= nil then return regressing == true end

        local success2, result2 = pcall(function()
            local regressing2 = model:FindFirstChild("Regressing")

            if regressing2 then
                if regressing2:IsA("ValueObject") or regressing2:IsA("BoolValue") then
                    return regressing2.Value == true
                end

                return true
            end

            return model.Regressing == true
        end)

        if success2 and result2 == true then return true end

        local hitBox = model:FindFirstChild("HitBox")
            or model:FindFirstChild("Hitbox")
            or model:FindFirstChild("Engine")
            or model:IsA("Model") and model.PrimaryPart
            or model:FindFirstChildWhichIsA("BasePart")

        if hitBox then
            local regressing2 = hitBox:GetAttribute("Regressing")
            if regressing2 == true then return true end
            local regressing3 = hitBox:FindFirstChild("Regressing")

            if regressing3 then
                if regressing3:IsA("ValueObject") or regressing3:IsA("BoolValue") then
                    return regressing3.Value == true
                end

                return true
            end
        end

        return false
    end

    function getGeneratorAnalytics(instance2_2)
        if not instance2_2 then
            return 0, nil, ""
        end

        local object3Item = object3[instance2_2]

        if not object3Item then
            return 0, nil, ""
        end

        return object3Item.smoothedSpeed or 0, object3Item.etaSeconds, object3Item.etaFormatted or ""
    end

    local function fnGeneratorESP()
        local now = tick()

        local alertThresholdEnabled = settings2.MasterESP
            and settings2.GeneratorESP
            and settings2.GeneratorESP.Enabled
            and settings2.GeneratorESP.AlertThresholdEnabled

        local alertThreshold = settings2.GeneratorESP and settings2.GeneratorESP.AlertThreshold or 90

        for _, instance2 in ipairs(cachedGenerators or {}) do
            if not instance2 or not instance2.Parent then continue end

            if isGeneratorCompleted(instance2) then
                object3[instance2] = nil
                continue
            end

            local generatorProgress = getGeneratorProgress(instance2)
            local object3Item = object3[instance2]

            if not object3Item then
                object3[instance2] = {
                    lastProgress = generatorProgress,
                    lastTime = now,
                    history = {},
                    smoothedSpeed = 0,
                    smoothedETA = nil,
                    etaSeconds = nil,
                    etaFormatted = "",
                    alertTriggered = generatorProgress >= alertThreshold,
                }

                continue
            end

            local num2 = now - object3Item.lastTime

            if num2 >= 0.75 then
                local num3 = generatorProgress - object3Item.lastProgress
                local generatorRegressing = isGeneratorRegressing(instance2)
                local value = 0

                if num3 ~= 0 then
                    value = num3 / num2
                elseif generatorRegressing then
                    if object3Item.smoothedSpeed and object3Item.smoothedSpeed < 0 then
                        value = object3Item.smoothedSpeed
                    else
                        value = -0.5
                    end
                else
                    value = 0
                end

                table.insert(object3Item.history, value)

                if #object3Item.history > 5 then
                    table.remove(object3Item.history, 1)
                end

                local num4 = 0

                for _, historyItem in ipairs(object3Item.history) do
                    num4 = num4 + historyItem
                end

                local num5 = num4 / #object3Item.history
                local smoothedSpeed = object3Item.smoothedSpeed or 0
                local smoothedSpeed2 = smoothedSpeed + (num5 - smoothedSpeed) * 0.25

                if math.abs(smoothedSpeed2) < 0.05 then
                    smoothedSpeed2 = 0
                end

                local etaSeconds = nil
                local str = ""

                if smoothedSpeed2 > 0.1 then
                    local num6 = 100 - generatorProgress
                    local num7 = math.max(0, num6 / smoothedSpeed2)
                    local smoothedETA = object3Item.smoothedETA or num7
                    local smoothedETA2 = smoothedETA + (num7 - smoothedETA) * 0.2
                    object3Item.smoothedETA = smoothedETA2
                    etaSeconds = smoothedETA2

                    if etaSeconds < 60 then
                        str = string.format("%ds", math.ceil(etaSeconds))
                    else
                        local num8 = math.floor(etaSeconds / 60)
                        local num9 = math.ceil(etaSeconds % 60)
                        str = string.format("%dm %02ds", num8, num9)
                    end
                else
                    object3Item.smoothedETA = nil
                end

                object3Item.smoothedSpeed = smoothedSpeed2
                object3Item.etaSeconds = etaSeconds
                object3Item.etaFormatted = str
                object3Item.lastProgress = generatorProgress
                object3Item.lastTime = now

                if alertThresholdEnabled then
                    if generatorProgress >= alertThreshold then
                        if not object3Item.alertTriggered then
                            object3Item.alertTriggered = true

                            local flag8 = object3Item.etaFormatted
                                and object3Item.etaFormatted ~= ""
                                and "ETA: " .. object3Item.etaFormatted or "Nearly Complete!"

                            showNotification("Generator Alert", string.format(
                                "Generator reached %d%% progress! (%s)",
                                math.floor(generatorProgress),
                                flag8
                            ), "warning")
                        end
                    else
                        if generatorProgress < alertThreshold - 5 then
                            object3Item.alertTriggered = false
                        end
                    end
                end
            end
        end
    end

