            local index = table.find(cachedPallets, instance2)

            if index then
                table.remove(cachedPallets, index)
            end

            pcall(function()
                removeModelESP(instance2, "Pallet")
            end)
        elseif name == "Window" or name:lower():find("window") or name == "Vault" or name:lower():find("vault") then
            local index = table.find(cachedVaults, instance2)

            if index then
                table.remove(cachedVaults, index)
            end

            pcall(function()
                removeModelESP(instance2, "Vault")
            end)
        elseif name == "VaultTrigger" or name:lower():find("vaulttrigger") then
            local parent = instance2.Parent

            if parent then
                local index = table.find(cachedVaults, parent)

                if index then
                    table.remove(cachedVaults, index)
                end

                pcall(function()
                    removeModelESP(parent, "Vault")
                end)
            end
        elseif name == "BloodEffect" then
            local index = table.find(cachedBloodEffects, instance2)

            if index then
                table.remove(cachedBloodEffects, index)
            end

            pcall(function()
                removeModelESP(instance2, "BloodEffect")
            end)
        elseif name == "Hook" or name == "HookPoint" then
            local index = table.find(cachedHooks, instance2)

            if index then
                table.remove(cachedHooks, index)

                pcall(function()
                    removeModelESP(instance2, "Hook")
                end)
            else
                for i = #cachedHooks, 1, -1 do
                    local instance3 = cachedHooks[i]

                    if instance3 == instance2 or instance3:IsDescendantOf(instance2) then
                        table.remove(cachedHooks, i)

                        pcall(function()
                            removeModelESP(instance3, "Hook")
                        end)
                    end
                end
            end
        elseif name == "Gate" or name == "ESCAPEGATE" or name == "ExitLever" or table.find(cachedGates, instance2) then
            local index = table.find(cachedGates, instance2)

            if index then
                table.remove(cachedGates, index)
            end

            pcall(function()
                removeModelESP(instance2, "Gate")
            end)
        elseif name == "BearTrap" then
            local index = table.find(cachedBearTraps, instance2)

            if index then
                table.remove(cachedBearTraps, index)
            end

            pcall(function()
                removeModelESP(instance2, "BearTrap")
            end)
        elseif name == "Pumpkin"
            or instance2.Parent and instance2.Parent.Name == "Pumpkins"
            or table.find(cachedPumpkins, instance2) then
            local index = table.find(cachedPumpkins, instance2)

            if index then
                table.remove(cachedPumpkins, index)
            end

            pcall(function()
                removeModelESP(instance2, "Pumpkins")
            end)
        end
    end

