    _G.VD_BLACKLISTED_ANIMATION_IDS = blacklistedAnimationIds
    _G.VD_LoggedAnimations = _G.VD_LoggedAnimations or {}

    _G.VD_BlacklistAnimation = function(value)
        if not value then return false end
        local str4 = string.match(tostring(value), "%d+") or ""

        if str4 ~= "" then
            blacklistedAnimationIds[str4] = true

            if _G.VD_LoggedAnimations[str4] then
                _G.VD_LoggedAnimations[str4].blacklisted = true
            end

            print("[VD PARRY] Added animation ID to Blacklist: " .. str4)
            warn("[VD PARRY] Blacklisted: " .. str4)

            pcall(function()
                if rconsoleprint then
                    rconsoleprint("@@RED@@[VD BLACKLIST] Added: " .. str4 .. "\n")
                end
            end)

            return true
        end

        return false
    end

    _G.VD_UnblacklistAnimation = function(value)
        if not value then return false end
        local str4 = string.match(tostring(value), "%d+") or ""

        if str4 ~= "" then
            blacklistedAnimationIds[str4] = nil

            if _G.VD_LoggedAnimations[str4] then
                _G.VD_LoggedAnimations[str4].blacklisted = false
            end

            print("[VD PARRY] Removed animation ID from Blacklist: " .. str4)
            warn("[VD PARRY] Unblacklisted: " .. str4)

            pcall(function()
                if rconsoleprint then
                    rconsoleprint("@@GREEN@@[VD BLACKLIST] Removed: " .. str4 .. "\n")
                end
            end)

            return true
        end

        return false
    end

    _G.VD_PrintLoggedAnimations = function()
        print("=== VD LOGGED KILLER ANIMATIONS ===")

        if not _G.VD_LoggedAnimations or not next(_G.VD_LoggedAnimations) then
            print("No killer animations logged yet.")
            return
        end

        for k, loggedAnimation in pairs(_G.VD_LoggedAnimations) do
            print(string.format(
                "ID: %s | Killer: %s | Prio: %s | Loop: %s | BL: %s | Name: '%s' | Track: '%s' | Time: %s",
                tostring(k),
                tostring(loggedAnimation.killer),
                tostring(loggedAnimation.priority),
                tostring(loggedAnimation.looped),
                tostring(loggedAnimation.blacklisted),
                tostring(loggedAnimation.name),
                tostring(loggedAnimation.track),
                tostring(loggedAnimation.time)
            ))
        end
    end

    local list7 = {}

    function updateSCPCache()
        local list8 = {}
        local map7 = {}

        local function fnInsert(value)
            if value and not map7[value] then
                map7[value] = true
                table.insert(list8, value)
            end
        end

        local map8 = workspace:FindFirstChild("Map")

        if map8 then
            for _, name in ipairs({"1", "2"}) do
                local instance2 = map8:FindFirstChild(name)

                if instance2 then
                    for _, child in ipairs(instance2:GetChildren()) do
                        if child:IsA("Model") then
                            fnInsert(child)
                        end
                    end
                end
            end

            local function fnMatch(name)
                return string.match(name:lower(), "^scp%d*$") ~= nil
            end

            for _, child in ipairs(map8:GetChildren()) do
                if child.Name ~= "1" and child.Name ~= "2" then
                    if child:IsA("Model") and fnMatch(child.Name) then
                        fnInsert(child)
                    elseif child:IsA("Folder") or child:IsA("Model") then
                        for _, child2 in ipairs(child:GetChildren()) do
                            if child2:IsA("Model") and fnMatch(child2.Name) then
                                fnInsert(child2)
                            end
                        end
                    end
                end
            end

            for _, child in ipairs(map8:GetChildren()) do
                if child:IsA("Model") and child ~= localPlayer.Character then
                    local cured = child:GetAttribute("Cured")

                    if tonumber(cured) == 3 then
                        fnInsert(child)
                    end
                end
            end
        end

        list7 = list8
    end

    local v4 = nil
    local str4 = "Unknown Map"

    function getMapName()
        local success2, result2 = pcall(function()
            return game:GetService("Players").LocalPlayer.PlayerGui.Darkness.Frame.MapInfo.MapTitle.Text
        end)

        if success2 and result2 and result2 ~= "" then
            if result2:upper() == "NOSTROMO" then return "Loading..." end
            return result2
        end

        local map7 = workspace:FindFirstChild("Map")

        if not map7 then
            v4 = nil
            str4 = "Unknown Map"
            return str4
        end

        local model = map7:FindFirstChildOfClass("Model") or map7:FindFirstChildOfClass("Folder") or map7
        if model == v4 and str4 ~= "Unknown Map" then return str4 end
        v4 = model

        if map7:FindFirstChild("HooksMeat", true) then
            str4 = "BLOODBATH! Club"
            return str4
        end

        if map7:FindFirstChild("Rooftop", true) then
            str4 = "Mercy Hospital Rooftop"
            return str4
        end

        if map7:FindFirstChild("inviswallasylum", true) then
            str4 = "Mount Massive Asylum"
            return str4
        end

        if map7:FindFirstChild("Tesla", true) then
            str4 = "Site 68"
            return str4
        end

        if map7:FindFirstChild("Breakwater", true) then
            str4 = "The Bay Harbor"
            return str4
        end

        if map7:FindFirstChild("RockVar0", true) then
            str4 = "Woodview Cabin"
            return str4
        end

        local model2 = map7:FindFirstChild("Model", true)

        if model2 then
            local position = model2:GetPivot().Position

            if (position - Vector3.new(-811.4, 212.8, -7774.5)).Magnitude < 100 then
                str4 = "Firelink Shrine"
                return str4
            end

            if (position - Vector3.new(1114.67, -16.92, -12.99)).Magnitude < 100 then
                str4 = "Valdelobos Village"
                return str4
            end
        end

        str4 = "Unknown Map"
        return str4
    end

    function applyBlockInteractions()
        pcall(function()
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            remotes = remotes and remotes:FindFirstChild("Window")
            remotes = remotes and remotes:FindFirstChild("VaultEvent")

            if remotes then
                for _, instance2 in ipairs(cachedVaults) do
                    if instance2 and instance2.Parent then
                        for _, descendant in ipairs(instance2:GetDescendants()) do
                            if descendant.Name == "VaultTrigger" then
                                remotes:FireServer(descendant, true)
                            end
                        end
                    end
                end
            end
        end)

        pcall(function()
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            remotes = remotes and remotes:FindFirstChild("Pallet")
            remotes = remotes and remotes:FindFirstChild("PalletSlideEvent")

            if remotes then
                for _, instance2 in ipairs(cachedPallets) do
                    if instance2 and instance2.Parent then
                        for _, descendant in ipairs(instance2:GetDescendants()) do
                            if descendant.Name == "PalletPointSlide" or descendant.Name:find("Slide") then
                                remotes:FireServer(descendant, true)
                            end
                        end
                    end
                end
            end
        end)
    end

    function releaseBlockInteractions()
        _G.VD_ReleasingBlockInteractions = true

        pcall(function()
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            remotes = remotes and remotes:FindFirstChild("Window")
            remotes = remotes and remotes:FindFirstChild("VaultCompleteEvent")

            if remotes then
                local map7 = workspace:FindFirstChild("Map")
                local map7_2 = map7 or workspace

                for _, descendant in ipairs(map7_2:GetDescendants()) do
                    if descendant.Name == "VaultTrigger" then
                        remotes:FireServer(descendant, false)
                    end
                end
            end
        end)

        _G.VD_ReleasingBlockInteractions = false

        pcall(function()
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            remotes = remotes and remotes:FindFirstChild("Pallet")
            remotes = remotes and remotes:FindFirstChild("PalletSlideCompleteEvent")

            if remotes then
                for _, instance2 in ipairs(cachedPallets) do
                    if instance2 and instance2.Parent then
                        for _, descendant in ipairs(instance2:GetDescendants()) do
                            if descendant.Name == "PalletPointSlide" or descendant.Name:find("Slide") then
                                remotes:FireServer(descendant)
                            end
                        end
                    end
                end
            end
        end)
    end

    do
        local flag9 = false

        function scanMapObjects()
            if flag9 then return end

            if isInLobby and isInLobby() then
                table.clear(cachedGenerators)
                table.clear(cachedBearTraps)
                table.clear(cachedHooks)
                table.clear(cachedPallets)
                table.clear(cachedVaults)
                return
            end

            flag9 = true

            task.spawn(function()
                local list8, list9, list10, list11, list12, list13, list14 = {}, {}, {}, {}, {}, {}, {}
                local map7 = {}
                pcall(updateSCPCache)

                pcall(function()
                    object = setmetatable({}, {__mode = "k"})
                    object2 = setmetatable({}, {__mode = "kv"})

                    if originalCanCollide then
                        for k, _ in pairs(originalCanCollide) do
                            if not k or not k.Parent then
                                originalCanCollide[k] = nil
                            end
                        end
                    end
                end)

                local players = Players:GetPlayers()
                local map8 = {}

                for _, player in ipairs(players) do
                    if player.Character then
                        map8[player.Character] = true
                    end
                end

                local map9 = workspace:FindFirstChild("Map")
                local descendants = map9 and map9:GetDescendants() or workspace:GetDescendants()

                for i, descendant in ipairs(descendants) do
                    if i % 300 == 0 then
                        task.wait()
                    end

                    local name = descendant.Name

                    if (name == "Generator" or name:lower():find("generator")) and descendant:IsA("Model") then
                        table.insert(list8, descendant)
                    elseif descendant:IsA("Model") and (descendant.Parent and descendant.Parent.Name == "Pallets"
                        or descendant.Name == "Pallet"
                        or descendant:FindFirstChild("Intact")) then
                        table.insert(list10, descendant)
                    elseif descendant.Name == "BearTrap"
                        or CollectionService and CollectionService:HasTag(descendant, "BearTrap") then
                        table.insert(list14, descendant)
                    elseif name == "Window"
                        or name:lower():find("window")
                        or name == "Vault"
                        or name:lower():find("vault") then
                        local bottom = descendant:FindFirstChild("bottom") or descendant:FindFirstChild("Bottom")
                        local inviswall = descendant:FindFirstChild("inviswall") or descendant:FindFirstChild("Inviswall")
                        local vaulttrigger = descendant:FindFirstChild("vaulttrigger") or descendant:FindFirstChild("VaultTrigger")

                        if not (bottom and inviswall and vaulttrigger) then
                            for _, child in ipairs(descendant:GetChildren()) do
                                local str = child.Name:lower()

                                if str == "bottom" then
                                    bottom = true
                                elseif str == "inviswall" then
                                    inviswall = true
                                elseif str == "vaulttrigger" then
                                    vaulttrigger = true
                                end
                            end
                        end

                        if bottom and inviswall and vaulttrigger then
                            table.insert(list11, descendant)
                        end
                    elseif name == "BloodEffect" and descendant:IsA("BasePart") then
                        table.insert(list12, descendant)
                    elseif name == "Hook" or name == "HookPoint" then
                        local flag10 = false
                        local descendant2 = descendant

                        while descendant2 and descendant2 ~= workspace and descendant2 ~= map9 do
                            if map8[descendant2] then
                                flag10 = true
                                break
                            end

                            descendant2 = descendant2.Parent
                        end

                        if not flag10 then
                            local descendant3 = nil

                            if descendant:IsA("BasePart") then
                                descendant3 = descendant
                            elseif descendant:IsA("Model") or descendant:IsA("Folder") then
                                descendant3 = descendant:FindFirstChild("HookPoint")
                                    or descendant:IsA("Model") and descendant.PrimaryPart
                                    or descendant:FindFirstChild("Handle")
                                    or descendant:FindFirstChildWhichIsA("BasePart")
                            end

                            if descendant3 and not map7[descendant3] then
                                map7[descendant3] = true
                                table.insert(list9, descendant3)
                            end
                        end
                    elseif (name == "ExitLever"
                        or descendant:FindFirstChild("ExitLever", true)
                        or descendant:FindFirstChild("ExitLever")) and not (name:lower():find("spot")
                        or name:lower():find("spawn")
                        or name:lower():find("marker")
                        or name:lower():find("point")) then
                        local descendant2 = descendant.Name == "ExitLever" and descendant
                            or descendant:FindFirstChild("ExitLever", true)
                            or descendant:FindFirstChild("ExitLever")

                        if descendant2 and not table.find(list13, descendant2) then
                            table.insert(list13, descendant2)
                        end
                    end
                end

                cachedGenerators = list8
                cachedHooks = list9
                cachedPallets = list10
                cachedVaults = list11
                cachedBloodEffects = list12

                if map9 then
                    for _, child in ipairs(map9:GetChildren()) do
                        local str = child.Name:lower()
                        local foundIndex = str:find("spot") or str:find("spawn") or str:find("marker") or str:find("point")

                        if not foundIndex then
                            local child2 = child.Name == "ExitLever" and child
                                or child:FindFirstChild("ExitLever", true)
                                or child:FindFirstChild("ExitLever")

                            if child2 and not table.find(list13, child2) then
                                table.insert(list13, child2)
                            end
                        end
                    end
                end

                local list15 = {}
                local pumpkins = map9 and map9:FindFirstChild("Pumpkins")

                if pumpkins then
                    for _, child in ipairs(pumpkins:GetChildren()) do
                        if not child:IsA("Folder") then
                            local child2 = child:IsA("Model") and child or child:IsA("BasePart") and child

                            if child2 and not table.find(list15, child2) then
                                table.insert(list15, child2)
                            end
                        else
                            for _, child2 in ipairs(child:GetChildren()) do
                                local child2_2 = child2:IsA("Model") and child2 or child2:IsA("BasePart") and child2

                                if child2_2 and not table.find(list15, child2_2) then
                                    table.insert(list15, child2_2)
                                end
                            end
                        end
                    end
                end

                for _, descendant in ipairs(map9:GetDescendants()) do
                    if descendant.Name ~= "Pumpkins"
                        and descendant.Name:lower():find("pumpkin")
                        and not descendant:IsA("Folder") then
                        local descendant2 = descendant:IsA("Model") and descendant or descendant:IsA("BasePart") and descendant

                        if descendant2 and not table.find(list15, descendant2) then
