    function createPlayerESP(entity)
        if ActiveESP.Players[entity] then return end
        local highlight = Instance.new("Highlight")
        highlight.FillTransparency = settings2.ESPFillTransparency or 0.6
        highlight.OutlineTransparency = settings2.ESPOutlineTransparency or 0.1
        highlight.Enabled = false
        highlight.Parent = highlightParent
        local billboardGui = Instance.new("BillboardGui")
        billboardGui.AlwaysOnTop = true
        billboardGui.StudsOffset = Vector3.new(0, 3.5 + (settings2.ESPPositionY or 0), 0)
        billboardGui.Enabled = false
        billboardGui.Parent = billboardParent
        local frame = Instance.new("Frame")
        frame.Name = "Container"
        frame.BackgroundTransparency = 1
        frame.BorderSizePixel = 0
        frame.Parent = billboardGui
        local uiCorner = Instance.new("UICorner")
        uiCorner.CornerRadius = UDim.new(0, 6)
        uiCorner.Parent = frame
        local uiStroke = Instance.new("UIStroke")
        uiStroke.Thickness = 1
        uiStroke.Transparency = 1
        uiStroke.Parent = frame
        local fontItem = Enum.Font[settings2.ESPFont] or Enum.Font.Ubuntu
        local ubuntu = settings2.ESPFont == "GothamBold" and Enum.Font.Ubuntu or fontItem
        local textLabel = Instance.new("TextLabel")
        textLabel.BackgroundTransparency = 1
        textLabel.TextColor3 = settings2.ESPTextColorMode == "Custom" and settings2.ESPTextColor or Color3.fromRGB(255, 255, 255)
        textLabel.Font = fontItem
        textLabel.TextStrokeColor3 = settings2.ESPTextOutlineColor or Color3.fromRGB(0, 0, 0)
        textLabel.TextStrokeTransparency = 0.4
        textLabel.Parent = frame
        local textLabel2 = Instance.new("TextLabel")
        textLabel2.BackgroundTransparency = 1
        textLabel2.TextColor3 = settings2.ESPTextColorMode == "Custom" and settings2.ESPTextColor or Color3.fromRGB(220, 220, 220)
        textLabel2.Font = ubuntu
        textLabel2.TextStrokeColor3 = settings2.ESPTextOutlineColor or Color3.fromRGB(0, 0, 0)
        textLabel2.TextStrokeTransparency = 0.5
        textLabel2.Parent = frame

        ActiveESP.Players[entity] = {
            Highlight = highlight,
            Billboard = billboardGui,
            Container = frame,
            ContainerStroke = uiStroke,
            NameLabel = textLabel,
            InfoLabel = textLabel2,
            Tracer = nil,
            CurrentCharacter = nil,
            LastAuraEnabled = nil,
            LastHighlightColor = nil,
            LastBillboardEnabled = nil,
            LastNameText = nil,
            LastNameColor = nil,
            LastInfoText = nil,
            LastHookedProgressVal = nil,
            LastHookedChangeTime = 0,
            LastESPStyle = nil,
            LastIsMobile = nil,
        }
    end

    local function fnTracer(player, visible)
        local tracer = player.Tracer
        if not tracer then return end

        pcall(function()
            if type(tracer) == "table" then
                for _, tracerItem in pairs(tracer) do
                    if type(tracerItem) == "table" or type(tracerItem) == "userdata" then
                        pcall(function()
                            tracerItem.Visible = visible
                        end)
                    end
                end
            elseif typeof(tracer) == "Instance" then
                tracer.Visible = visible
            end
        end)
    end

    function removePlayerESP(k)
        local player = ActiveESP.Players[k]

        if player then
            if player.Highlight then
                pcall(function()
                    player.Highlight:Destroy()
                end)
            end

            if player.Billboard then
                pcall(function()
                    player.Billboard:Destroy()
                end)
            end

            if player.Tracer then
                pcall(function()
                    if type(player.Tracer) == "table" then
                        for _, tracerItem in pairs(player.Tracer) do
                            if type(tracerItem) == "table" or type(tracerItem) == "userdata" then
                                pcall(function()
                                    tracerItem:Remove()
                                end)
                            elseif typeof(tracerItem) == "Instance" then
                                pcall(function()
                                    tracerItem:Destroy()
                                end)
                            end
                        end
                    elseif typeof(player.Tracer) == "Instance" then
                        player.Tracer:Destroy()
                    end
                end)

                player.Tracer = nil
            end

            ActiveESP.Players[k] = nil
        end
    end

    local flag9 = false

    function updatePlayersESP()
        if isSpectating() then
            if not flag9 then
                for _, player in ipairs(Players:GetPlayers()) do
                    local player2 = ActiveESP.Players[player]

                    if player2 then
                        if player2.LastAuraEnabled ~= false then
                            player2.Highlight.Enabled = false
                            player2.LastAuraEnabled = false
                        end

                        if player2.LastBillboardEnabled ~= false then
                            player2.Billboard.Enabled = false
                            player2.LastBillboardEnabled = false
                        end

                        if player2.Tracer then
                            fnTracer(player2, false)
                        end

                        player2.CurrentCharacter = nil
                    end
                end

                flag9 = true
            end

            return
        end

        local enabled = settings2.MeESP and settings2.MeESP.Enabled

        if not settings2.MasterESP
            or not settings2.KillerESP.Enabled and not settings2.SurvivorESP.Enabled and not enabled then
            if not flag9 then
                for _, player in ipairs(Players:GetPlayers()) do
                    local player2 = ActiveESP.Players[player]

                    if player2 then
                        if player2.LastAuraEnabled ~= false then
                            player2.Highlight.Enabled = false
                            player2.LastAuraEnabled = false
                        end

                        if player2.LastBillboardEnabled ~= false then
                            player2.Billboard.Enabled = false
                            player2.LastBillboardEnabled = false
                        end

                        if player2.Tracer then
                            fnTracer(player2, false)
                        end

                        player2.CurrentCharacter = nil
                    end
                end

                flag9 = true
            end

            return
        end

        flag9 = false
        local espStyle = settings2.ESPStyle or "Standard"

        if not _G.VD_EspActiveTargets then
            _G.VD_EspActiveTargets = {}
            _G.VD_EspKnownPlayerChars = {}
            _G.VD_CachedBotsList = {}
            _G.VD_LastBotScanTime = 0
        end

        local espActiveTargets = _G.VD_EspActiveTargets
        local espKnownPlayerChars = _G.VD_EspKnownPlayerChars
        table.clear(espActiveTargets)
        table.clear(espKnownPlayerChars)

        for _, player in ipairs(Players:GetPlayers()) do
            table.insert(espActiveTargets, {entity = player, char = player.Character, isBot = false})

            if player.Character then
                espKnownPlayerChars[player.Character] = true
            end
        end

        local now = tick()

        if now - _G.VD_LastBotScanTime >= 0.8 then
            _G.VD_LastBotScanTime = now
            table.clear(_G.VD_CachedBotsList)

            for _, child in ipairs(workspace:GetChildren()) do
                if child:IsA("Model") and child ~= localPlayer.Character and not espKnownPlayerChars[child] then
                    local humanoid = child:FindFirstChildOfClass("Humanoid")
                    local humanoidRootPart2 = child:FindFirstChild("HumanoidRootPart")

                    if humanoid and humanoidRootPart2 then
                        local sCPName = isSCPName and isSCPName(child.Name) or child:GetAttribute("Cured") == 3

                        if not sCPName
                            and (humanoid.Health > 0 or child:GetAttribute("Knocked") or child:GetAttribute("IsHooked")) then
                            table.insert(_G.VD_CachedBotsList, child)
                        end
                    end
                end
            end

            for _, name in ipairs({"Survivors", "Killers", "Bots"}) do
                local instance2 = workspace:FindFirstChild(name)

                if instance2 then
                    for _, child in ipairs(instance2:GetChildren()) do
                        if child:IsA("Model")
                            and child ~= localPlayer.Character
                            and not espKnownPlayerChars[child] then
                            local humanoid = child:FindFirstChildOfClass("Humanoid")
                            local humanoidRootPart2 = child:FindFirstChild("HumanoidRootPart")

                            if humanoid and humanoidRootPart2 then
                                local sCPName = isSCPName and isSCPName(child.Name) or child:GetAttribute("Cured") == 3

                                if not sCPName and (humanoid.Health > 0
                                    or child:GetAttribute("Knocked")
                                    or child:GetAttribute("IsHooked")) then
                                    table.insert(_G.VD_CachedBotsList, child)
                                end
                            end
                        end
                    end
                end
            end
        end

        for _, cachedBot in ipairs(_G.VD_CachedBotsList) do
            if cachedBot
                and cachedBot.Parent
                and cachedBot:IsDescendantOf(workspace)
                and not espKnownPlayerChars[cachedBot] then
                local humanoid = cachedBot:FindFirstChildOfClass("Humanoid")

                if humanoid
                    and (humanoid.Health > 0 or cachedBot:GetAttribute("Knocked") or cachedBot:GetAttribute("IsHooked")) then
                    table.insert(espActiveTargets, {entity = cachedBot, char = cachedBot, isBot = true})
                    espKnownPlayerChars[cachedBot] = true
                end
            end
        end

        for _, espActiveTarget in ipairs(espActiveTargets) do
            local entity = espActiveTarget.entity
            local isBot = espActiveTarget.isBot
            local char = espActiveTarget.char
            local flag10 = not isBot and entity == localPlayer

            if flag10 and not (settings2.MeESP and settings2.MeESP.Enabled) then
                local player = ActiveESP.Players[localPlayer]

                if player then
                    if player.Highlight then
                        player.Highlight.Enabled = false
                    end

                    if player.Billboard then
                        player.Billboard.Enabled = false
                    end

                    if player.Tracer then
                        fnTracer(player, false)
                    end

                    player.LastAuraEnabled = false
                    player.LastBillboardEnabled = false
                    player.CurrentCharacter = nil
                end

                continue
            end

            createPlayerESP(entity)
            local player = ActiveESP.Players[entity]
            if not player then continue end
            local humanoidRootPart2 = char and char:FindFirstChild("HumanoidRootPart")
            local isKiller = player.IsKiller
            local isSurvivor = player.IsSurvivor
            local flag11 = false

            if flag10 then
                isKiller = false
                isSurvivor = false
                player.IsKiller = false
                player.IsSurvivor = false
            elseif isBot then
                local name = char.Parent and char.Parent.Name

                if name == "Killers"
                    or char:FindFirstChild("StunEvent")
