                    isKiller = false
                end

                player.IsKiller = isKiller
                player.IsSurvivor = isSurvivor
            elseif isKiller == nil or player.CurrentCharacter ~= char then
                local team = entity.Team
                isKiller = team and team.Name == "Killer"
                isSurvivor = team and team.Name == "Survivors"

                if not team then
                    local str = entity.Name:lower()

                    if str:find("killer") then
                        isKiller = true
                    elseif str:find("survivor") then
                        isSurvivor = true
                    end
                end

                if char then
                    local name = char.Parent and char.Parent.Name

                    if name == "Killers" or char:FindFirstChild("StunEvent") then
                        isKiller = true
                        isSurvivor = false
                    elseif char.Name == "Veil" or char.Parent and char.Parent.Name == "Veil" then
                        isKiller = true
                        isSurvivor = false
                    end

                    local cured = char:GetAttribute("Cured")

                    if cured == 3 then
                        flag11 = true
                        isKiller = true
                        isSurvivor = false
                    end
                end

                if isKiller == nil then
                    isKiller = false
                end

                if isSurvivor == nil then
                    isSurvivor = false
