                        flag11 = true
                        isKiller = true
                        isSurvivor = false
                    end
                end
            end

            local flag12 = false
            local eSPColor = Color3.fromRGB(255, 255, 255)
            local flag13 = false
            local flag14 = false

            if char then
                local value = readModelValue(char, "Knocked")

                if value == true or tostring(value):lower() == "true" or value == 1 then
                    flag13 = true
                end

                local flag15 = readModelValue(char, "IsHooked") == true or char:GetAttribute("IsHooked") == true

                if flag15 then
