                    local str = readModelValue(char, "HookedProgress")

                    if str and tonumber(str) then
                        local num4 = tonumber(str)

                        if player.LastHookedProgressVal == nil then
                            player.LastHookedProgressVal = num4
                            player.LastHookedChangeTime = 0
                        elseif player.LastHookedProgressVal ~= num4 then
                            player.LastHookedProgressVal = num4
                            player.LastHookedChangeTime = os.clock()
                        end

                        if os.clock() - (player.LastHookedChangeTime or 0) < 2 then
                            flag14 = true
                        end
                    else
                        player.LastHookedProgressVal = nil
                    end
                end
            end

            local distance = flag10 and 0 or getDistance(entity, humanoidRootPart2)
            local flag15 = flag10 or distance <= settings2.ESPRange

            if flag10 and settings2.MeESP and settings2.MeESP.Enabled then
                flag12 = true
                eSPColor = getESPColor("Me")
            elseif flag11 and settings2.KillerESP.Enabled and flag15 then
                flag12 = true
                local scp = settings2.ESPColors and settings2.ESPColors.SCP
