                local aura = flag10 and settings2.MeESP.Aura
                    or isKiller and settings2.KillerESP.Aura
                    or isSurvivor and settings2.SurvivorESP.Aura

                local flag16 = false

                if char.Parent and char.Parent ~= workspace then
                    if char.Parent:IsA("Model") and char.Parent:FindFirstChildOfClass("Humanoid") then
                        flag16 = true
                    elseif char.Parent.Name:lower():find("carry") or char.Parent.Name:lower():find("carried") then
                        flag16 = true
