                local distanceOpacityFactor = 1
                local espDistanceFadePlayers = settings2.ESPDistanceFade and settings2.ESPDistanceFadePlayers

                if espDistanceFadePlayers and distance then
                    if distance >= settings2.ESPFadeMax then
                        distanceOpacityFactor = 0
                    elseif distance > settings2.ESPFadeStart then
                        local num4 = settings2.ESPFadeMax - settings2.ESPFadeStart
