                        distanceOpacityFactor = 1 - num5 / num4
                    end
                end

                player.DistanceOpacityFactor = distanceOpacityFactor
                player.LastAuraEnabled = aura and distanceOpacityFactor > 0.005
                player.TargetHighlightVisible = true
                local espFillColor = settings2.ESPFillColorMode == "Custom" and settings2.ESPFillColor or eSPColor
                local espOutlineColor = settings2.ESPOutlineColorMode == "Custom" and settings2.ESPOutlineColor or eSPColor

