                        player.NameLabel.Size = UDim2.new(1, 0, 0.45, 0)
                        player.NameLabel.Position = UDim2.new(0, 0, 0.05, 0)
                        player.NameLabel.TextSize = espTextSize or lastIsMobile and 11 or 13
