                        if isKiller and settings2.KillerESP.SelectedKiller then
                            local selectedKiller = getSelectedKiller(entity)
                            str8 = str8 .. "Killer: " .. selectedKiller .. flag17
                        end

                        if isSurvivor and settings2.SurvivorESP.HealthState then
                            str8 = str8 .. "State: " .. str7 .. flag17
