    function getModelTargetPart(part)
        if part:IsA("Model") then
            local intact = part:FindFirstChild("Intact")

            if intact then
                if intact:IsA("BasePart") then return intact end

                if intact:IsA("Model") then
                    return intact.PrimaryPart or intact:FindFirstChildWhichIsA("BasePart")
                end
            end

            return part.PrimaryPart or part:FindFirstChildWhichIsA("BasePart")
        end

        if part:IsA("BasePart") then return part end
        return nil
    end

    function getVaultHighlightPart(part)
        local bottom = part:FindFirstChild("Bottom")

        if not bottom or not bottom:IsA("BasePart") then
            local modelTargetPart = getModelTargetPart(part)
            if modelTargetPart and modelTargetPart:IsA("BasePart") then return modelTargetPart end
            if part:IsA("BasePart") then return part end
            return part:FindFirstChildWhichIsA("BasePart") or part
        end

        local v5 = nil
        local huge = math.huge

        for _, descendant in ipairs(part:GetDescendants()) do
            if descendant:IsA("BasePart") and descendant ~= bottom and descendant.Name ~= "HumanoidRootPart" then
                if descendant.Transparency < 1 then
                    local distance = (descendant.Position - bottom.Position).Magnitude

                    if distance < huge then
                        huge = distance
                        v5 = descendant
                    end
                end
            end
        end

        return v5 or bottom
    end

