        textLabel.Parent = frame
        local modelTargetPart = getModelTargetPart(part)
        local part2 = part
        local highlight = nil
        local cartoonyBloodPuddle = nil

        if typeKey == "Gate" then
            local gatePartSafe = getGatePartSafe(part)

            local part3 = part.Name == "ExitLever" and part
                or part:FindFirstChild("ExitLever", true)
                or part:FindFirstChild("ExitLever")

            if gatePartSafe then
                modelTargetPart = gatePartSafe
                part2 = part3 and part3:IsA("Model") and part3 or gatePartSafe
            end
        elseif typeKey == "BearTrap" then
            if part:IsA("Folder") then
                part2 = modelTargetPart
                    or part:FindFirstChildWhichIsA("Model")
                    or part:FindFirstChildWhichIsA("BasePart")
            end
        elseif typeKey == "Pumpkins" then
            if part:IsA("BasePart")
                and part.Parent
                and part.Parent:IsA("Model")
                and part.Parent ~= workspace
                and part.Parent.Name ~= "Pumpkins" then
                part2 = part.Parent
            end
        elseif typeKey == "Vault" then
            part2 = getVaultHighlightPart(part)
        elseif typeKey == "Hook" then
            local part3 = part
            local part3_2 = nil
            local model = nil

            while part3 and part3 ~= workspace do
                if part3.Name == "Hook" then
                    part3_2 = part3
                    break
                end

                part3 = part3.Parent
            end

            if not part3_2 then
                if part.Parent and (part.Parent.Name == "Hook" or part.Parent.Name == "Model") then
                    part3_2 = part.Parent.Name == "Hook" and part.Parent or part.Parent.Parent
                end
            end

            if part3_2 then
                cartoonyBloodPuddle = part3_2:FindFirstChild("Cartoony Blood Puddle")
                    or part3_2:FindFirstChild("CartoonyBloodPuddle")
                    or part3_2:FindFirstChild("Blood Puddle")
                    or part3_2:FindFirstChild("BloodPuddle")

                if part3_2:IsA("Model") then
                    part2 = part3_2
                else
                    model = part3_2:FindFirstChild("Model") or part3_2:FindFirstChildWhichIsA("Model")
                    part2 = model or part
                end
            else
                local part4 = part

                while part4 and part4 ~= workspace do
                    if part4.Name == "Model" and part4:IsA("Model") then
                        model = part4
                        break
                    end

                    part4 = part4.Parent
                end

                if model then
                    part2 = model

                    if model.Parent then
                        cartoonyBloodPuddle = model.Parent:FindFirstChild("Cartoony Blood Puddle")
                    end
                end
            end

            if cartoonyBloodPuddle and (part2 ~= part3_2 or not (part3_2 and part3_2:IsA("Model"))) then
                highlight = Instance.new("Highlight")
                highlight.FillTransparency = settings2.ESPFillTransparency or 0.6
                highlight.OutlineTransparency = settings2.ESPOutlineTransparency or 0.1
                highlight.FillColor = settings2.ESPFillColorMode == "Custom" and settings2.ESPFillColor or eSPColor
                highlight.OutlineColor = settings2.ESPOutlineColorMode == "Custom" and settings2.ESPOutlineColor or eSPColor
                highlight.Adornee = cartoonyBloodPuddle
                highlight.Enabled = false
                highlight.Parent = highlightParent
            end
        end

        v5[part] = {
            Highlight = boxHandleAdornment,
            PuddleHighlight = highlight,
            BloodPuddle = cartoonyBloodPuddle,
            Billboard = billboardGui,
            Container = frame,
            ContainerStroke = uiStroke,
