    function manageHighlights()
        local list9 = {}

        for k, player in pairs(ActiveESP.Players) do
            if player.Highlight and player.LastAuraEnabled then
                table.insert(list9, {
                    data = player,
                    priority = 1,
                    dist = getDistance(k, player.Billboard and player.Billboard.Adornee),
                })
            else
                player.TargetHighlightVisible = false
            end
        end

        local list10 = {
            ActiveESP.SCPs,
            ActiveESP.Generators,
            ActiveESP.Hooks,
            ActiveESP.Pallets,
            ActiveESP.Vaults,
            ActiveESP.BloodEffects,
            ActiveESP.Gates,
            ActiveESP.BearTraps,
            ActiveESP.Pumpkins,
        }

        for i, list10Item in ipairs(list10) do
            local priority = 4

            if i == 1 then
                priority = 2
            elseif i == 2 or i == 7 or i == 8 then
                priority = 3
            end

            for k, list10ItemItem in pairs(list10Item) do
                if list10ItemItem.Highlight and list10ItemItem.LastAuraEnabled then
                    table.insert(list9, {
                        data = list10ItemItem,
                        priority = priority,
                        dist = getDistance(k, list10ItemItem.LastBillboardAdornee),
                    })
                else
                    list10ItemItem.TargetHighlightVisible = false
                end
            end
        end

        table.sort(list9, function(arg1, arg2)
            if arg1.priority ~= arg2.priority then return arg1.priority < arg2.priority end
            return arg1.dist < arg2.dist
        end)

        local num4 = 28

        for i, list9Item in ipairs(list9) do
            local enabled = i <= num4
            list9Item.data.TargetHighlightVisible = enabled

            if (settings2.ESPFadeDuration or 0.2) <= 0.01 then
                if list9Item.data.Highlight:IsA("Highlight") then
                    if list9Item.data.Highlight.Enabled ~= enabled then
                        list9Item.data.Highlight.Enabled = enabled
                    end
                elseif list9Item.data.Highlight:IsA("BoxHandleAdornment") then
                    if list9Item.data.Highlight.Visible ~= enabled then
                        list9Item.data.Highlight.Visible = enabled
                    end
                end

                if list9Item.data.PuddleHighlight and list9Item.data.PuddleHighlight:IsA("Highlight") then
                    if list9Item.data.PuddleHighlight.Enabled ~= enabled then
                        list9Item.data.PuddleHighlight.Enabled = enabled
                    end
                end
            end
        end
    end

    local list9 = nil

    function updateESPFadeTransitions(arg1)
        if not settings2.MasterESP then return end
        local performanceMode = settings2.PerformanceMode
        local espFadeDuration = performanceMode and 0 or settings2.ESPFadeDuration or 0.2
        local performanceMode2 = performanceMode or espFadeDuration <= 0.01
        local espFillTransparency = settings2.ESPFillTransparency or 0.6
        local espOutlineTransparency = settings2.ESPOutlineTransparency or 0.1

        local function fnHighlight(player, arg2)
            if not player or not player.Highlight then return end
            local distanceOpacityFactor = 0

            if player.TargetHighlightVisible ~= false and player.LastAuraEnabled then
                distanceOpacityFactor = player.DistanceOpacityFactor or 1
            end

            if player.CurrentAlpha == nil then
                player.CurrentAlpha = distanceOpacityFactor
            elseif performanceMode2 then
                player.CurrentAlpha = distanceOpacityFactor
            else
                local num4 = arg1 / espFadeDuration

                if player.CurrentAlpha < distanceOpacityFactor then
                    player.CurrentAlpha = math.min(distanceOpacityFactor, player.CurrentAlpha + num4)
                elseif player.CurrentAlpha > distanceOpacityFactor then
                    player.CurrentAlpha = math.max(distanceOpacityFactor, player.CurrentAlpha - num4)
                end
            end

            local currentAlpha = player.CurrentAlpha
            local enabled = currentAlpha > 0.005

            if player.LastFadeAlpha == currentAlpha
                and player.LastFadeFill == espFillTransparency
                and player.LastFadeOutline == espOutlineTransparency
                and player.LastFadeVis == enabled then
                return
            end

            player.LastFadeAlpha = currentAlpha
            player.LastFadeFill = espFillTransparency
            player.LastFadeOutline = espOutlineTransparency
            player.LastFadeVis = enabled

            if arg2 then
                if player.Highlight:IsA("BoxHandleAdornment") then
                    if player.Highlight.Visible ~= enabled then
                        player.Highlight.Visible = enabled
                    end

                    if enabled then
                        player.Highlight.Transparency = 1 - (1 - espFillTransparency) * currentAlpha
                    end
                end
            else
                if player.Highlight:IsA("Highlight") then
                    if player.Highlight.Enabled ~= enabled then
                        player.Highlight.Enabled = enabled
                    end

                    if enabled then
                        player.Highlight.FillTransparency = 1 - (1 - espFillTransparency) * currentAlpha
                        player.Highlight.OutlineTransparency = 1 - (1 - espOutlineTransparency) * currentAlpha
                    end
                end

                if player.PuddleHighlight and player.PuddleHighlight:IsA("Highlight") then
                    if player.PuddleHighlight.Enabled ~= enabled then
                        player.PuddleHighlight.Enabled = enabled
                    end

                    if enabled then
                        player.PuddleHighlight.FillTransparency = 1 - (1 - espFillTransparency) * currentAlpha
                        player.PuddleHighlight.OutlineTransparency = 1 - (1 - espOutlineTransparency) * currentAlpha
                    end
                end
            end
        end

        for _, player in pairs(ActiveESP.Players) do
            fnHighlight(player, false)
        end

        if not list9 then
            list9 = {
                ActiveESP.Generators,
                ActiveESP.Hooks,
                ActiveESP.Pallets,
                ActiveESP.BloodEffects,
                ActiveESP.Gates,
                ActiveESP.SCPs,
                ActiveESP.BearTraps,
                ActiveESP.Pumpkins,
            }
        end

        for _, list9Item in ipairs(list9) do
            for _, list9ItemItem in pairs(list9Item) do
                fnHighlight(list9ItemItem, false)
            end
        end

        for _, vault in pairs(ActiveESP.Vaults) do
            fnHighlight(vault, true)
        end
    end

