    function applyTheme(theme)
        currentThemeName = theme or "Default"
        local default = themes[currentThemeName] or themes.Default
        local bg = UI.Bg
        local sidebar = UI.Sidebar
        local card = UI.Card
        local elevated = UI.Elevated
        local stroke = UI.Stroke
        local strokeDim = UI.StrokeDim
        local accent = UI.Accent
        local accentCyan = UI.AccentCyan
        local accentGreen = UI.AccentGreen
        local accentRed = UI.AccentRed
        UI.Bg = default.Bg
        UI.Sidebar = default.Sidebar
        UI.Card = default.Card
        UI.Elevated = default.Elevated
        UI.Stroke = default.Stroke
        UI.StrokeDim = default.StrokeDim
        UI.Accent = default.Accent
        UI.AccentCyan = default.AccentCyan
        UI.AccentGreen = default.AccentGreen
        UI.AccentRed = default.AccentRed
        if not mainFrame then return end
        mainFrame.BackgroundColor3 = UI.Bg

        local v5 = settings2.CustomBackground
            and settings2.CustomBackground.Enabled
            and isPremiumActive()
            and map
            and (map.CustomBackground or map["Custom Background"])

        mainFrame.BackgroundTransparency = v5 and 1 or default.BgTrans
        _G.VD_MainStroke = mainFrame:FindFirstChildOfClass("UIStroke")

        if _G.VD_MainStroke then
            _G.VD_MainStroke.Color = UI.Stroke
            _G.VD_MainStroke.Thickness = 1
        end

        local sidebar2 = mainFrame:FindFirstChild("Sidebar")

        if sidebar2 then
            sidebar2.BackgroundColor3 = UI.Sidebar
            sidebar2.BackgroundTransparency = v5 and 0.85 or default.BgTrans
            local uiStroke = sidebar2:FindFirstChildOfClass("UIStroke")

            if uiStroke then
                uiStroke.Color = UI.StrokeDim
            end
        end

        for _, descendant in ipairs(screenGui:GetDescendants()) do
            if descendant:IsA("GuiObject") then
                if descendant.Name == "VD_CustomBg"
                    or descendant.Name == "VD_BgOverlay"
                    or imageLabel and descendant == imageLabel
                    or frame and descendant == frame then
                    if descendant.Name == "VD_CustomBg" or imageLabel and descendant == imageLabel then
                        pcall(function()
                            descendant.ImageColor3 = Color3.fromRGB(255, 255, 255)
                        end)
                    end

                    continue
                end

                local name = descendant.Name
                local str = name:lower()

                local flag10 = name == "LogoImage" or str:find("logo") ~= nil or name == "TitleLogo" or name == "HomeHeaderAvatar" or name == "WelcomeBackAvatar" or str:find("avatar") ~= nil or str:find("portrait") ~= nil or str:find("survivor") ~= nil or descendant:IsA("ImageLabel") and descendant.Image and (descendant.Image:find("rbxthumb://") ~= nil
                    or descendant.Image:find("roblox.com") ~= nil
                    or descendant.Image:find("dbd_hud_") ~= nil
                    or descendant.Image:find("VD_Logo") ~= nil)

                if flag10 then
                    if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
                        descendant.ImageColor3 = Color3.fromRGB(255, 255, 255)
                    elseif descendant:IsA("TextLabel") and name == "TitleLogo" then
                        descendant.TextColor3 = UI.Text
                    end

                    local uiStroke = descendant:FindFirstChildOfClass("UIStroke")

                    if uiStroke then
                        uiStroke.Color = UI.Accent
                    end

                    continue
                end

                if descendant.BackgroundColor3 == bg then
                    descendant.BackgroundColor3 = UI.Bg
                elseif descendant.BackgroundColor3 == sidebar then
                    descendant.BackgroundColor3 = UI.Sidebar
                elseif descendant.BackgroundColor3 == card then
                    descendant.BackgroundColor3 = UI.Card
                elseif descendant.BackgroundColor3 == elevated then
                    descendant.BackgroundColor3 = UI.Elevated
                elseif descendant.BackgroundColor3 == accent then
                    descendant.BackgroundColor3 = UI.Accent
                elseif descendant.BackgroundColor3 == accentCyan then
                    descendant.BackgroundColor3 = UI.AccentCyan
                elseif descendant.BackgroundColor3 == accentGreen then
                    descendant.BackgroundColor3 = UI.AccentGreen
                elseif descendant.BackgroundColor3 == accentRed then
                    descendant.BackgroundColor3 = UI.AccentRed
                elseif descendant.BackgroundColor3 == stroke then
                    descendant.BackgroundColor3 = UI.Stroke
                elseif descendant.BackgroundColor3 == strokeDim then
                    descendant.BackgroundColor3 = UI.StrokeDim
                end

                if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
                    local flag11 = name == "TabIcon" or name == "Icon" or name == "SearchIcon" or name:find("Chevron") ~= nil or name:find("Check") ~= nil or descendant.Parent and (descendant.Parent.Name:find("TabBtn") ~= nil
                        or descendant.Parent.Name:find("Toggle") ~= nil
                        or descendant.Parent.Name:find("Selector") ~= nil
                        or descendant.Parent.Name:find("Slider") ~= nil)

                    if flag11 then
                        if descendant.ImageColor3 == accent then
                            descendant.ImageColor3 = UI.Accent
                        elseif descendant.ImageColor3 == accentCyan then
                            descendant.ImageColor3 = UI.AccentCyan
                        elseif descendant.ImageColor3 == stroke then
                            descendant.ImageColor3 = UI.Stroke
                        elseif descendant.ImageColor3 == strokeDim then
                            descendant.ImageColor3 = UI.StrokeDim
                        end
                    end
                end

                if descendant:IsA("TextLabel") or descendant:IsA("TextBox") or descendant:IsA("TextButton") then
                    local flag11 = descendant:GetAttribute("ThemeAccentText") == true
                        or name == "PopupTitle"
                        or name == "GetKeyBtn"
                        or descendant.Parent and descendant.Parent.Name == "HeaderBanner"
                        or descendant.Parent and descendant.Parent.Name:find("MobileFloating_") ~= nil

                    if flag11 then
                        if descendant.TextColor3 == accent then
                            descendant.TextColor3 = UI.Accent
                        elseif descendant.TextColor3 == accentCyan then
                            descendant.TextColor3 = UI.AccentCyan
                        elseif descendant.TextColor3 == accentGreen then
                            descendant.TextColor3 = UI.AccentGreen
                        end
                    elseif descendant.TextColor3 == accentCyan then
                        descendant.TextColor3 = UI.AccentCyan
                    elseif descendant.TextColor3 == accentGreen then
                        descendant.TextColor3 = UI.AccentGreen
                    end
                end

                local uiStroke = descendant:FindFirstChildOfClass("UIStroke")

                if uiStroke then
                    if uiStroke.Color == stroke then
                        uiStroke.Color = UI.Stroke
                    elseif uiStroke.Color == strokeDim then
                        uiStroke.Color = UI.StrokeDim
                    elseif uiStroke.Color == accent then
                        uiStroke.Color = UI.Accent
                    end
                end

                if descendant.Name == "SectionLine" then
                    descendant.BackgroundColor3 = UI.StrokeDim
                end
            end
        end

        if searchBarContainer then
            searchBarContainer.BackgroundColor3 = UI.Card
        end

        if searchStroke then
            searchStroke.Color = UI.StrokeDim
        end

        if searchIconLbl then
            pcall(function()
                if searchIconLbl:IsA("ImageLabel") then
                    searchIconLbl.ImageColor3 = UI.TextSub
                else
                    searchIconLbl.TextColor3 = UI.Accent
                end
            end)
        end

        if searchBox then
            searchBox.TextColor3 = UI.Text
            searchBox.PlaceholderColor3 = UI.Muted
        end

        if clearSearchBtn then
            clearSearchBtn.TextColor3 = UI.TextSub
        end

        if searchBox and searchBox.Text ~= "" and updateSearchResults then
            local str = searchBox.Text:gsub("^%s*(.-)%s*$", ""):lower()

            if #str > 0 then
                pcall(updateSearchResults, str)
            end
        end

        if applyCustomBg then
            pcall(applyCustomBg)
        elseif _G.VD_ApplyCustomBg then
            pcall(_G.VD_ApplyCustomBg)
        end
    end

    local map9 = {}

    local function fnRevolverAimbot(value)
        if not value or value == "" then return nil end
        local str = tostring(value):lower():gsub("%s+", "")

        if str == "togglespeedboost" or str == "speedboost" then
            return settings2.SpeedBoostEnabled == true
        elseif str == "noturnspeedloss" or str == "preserveturnspeed" then
            return settings2.NoTurnSpeedLoss == true
        elseif str == "automoonwalk" or str == "moonwalk" then
            return settings2.AutoMoonwalk == true
        elseif str == "noclipvaultspallets" or str == "noclip" then
            return settings2.NoclipVaultsPallets == true
        elseif str == "autofleekiller" or str == "autoflee" then
            return settings2.AutoFleeKiller == true
        elseif str == "alwaysfastvault" or str == "fastvault" then
            return settings2.AlwaysFastVault == true
        elseif str == "fakevault" then
            return settings2.FakeVault == true
        elseif str == "instantheal" then
            return settings2.InstantHeal == true
        elseif str == "autoparry" then
            return settings2.AutoParry == true
        elseif str == "frenzyparry" then
            return settings2.FrenzyParry == true
        elseif str == "revolverautofarm" then
            return settings2.RevolverAutofarm == true
        elseif str == "revolveraimbot" or str == "aimbot" then
            return (settings2.RevolverAimbot and settings2.RevolverAimbot.Enabled) == true
        elseif str == "flowstateperk" or str == "flowstate" then
            return settings2.FlowstatePerk == true
        elseif str == "simulatequickrecovery" or str == "quickrecovery" then
            return settings2.SimulateQuickRecovery == true
        elseif str == "simulateperfectlanding" or str == "perfectlanding" then
            return settings2.SimulatePerfectLanding == true
        elseif str == "activefeaturesoverlay" or str == "activefeatures" then
            return settings2.ShowActiveFeatures == true
        elseif str == "spectatorlist" or str == "spectators" then
            return settings2.ShowSpectatorList == true
        elseif str == "nofog" then
            return settings2.NoFog == true
        elseif str == "dofremoval" or str == "removedof" then
            return settings2.RemoveDOF == true
        elseif str == "fullbright" then
            return settings2.FullBright == true
        elseif str == "noskillchecks" then
            return settings2.NoSkillChecks == true
        elseif str == "rainbowcharacter" or str == "rainbow" then
            return settings2.RainbowCharacter == true
        elseif str == "fakelag" then
            return settings2.FakeLag == true
        elseif str == "desync" then
            return settings2.Desync == true
        elseif str == "blockvaultpalletinteraction" or str == "blockvaults" or str == "blockpallets" then
            return settings2.BlockVaultPalletInteraction == true
        elseif settings2[value] ~= nil and type(settings2[value]) == "boolean" then
            return settings2[value] == true
        end

        for k, settings2Item in pairs(settings2) do
            if type(settings2Item) == "boolean" then
                local str5 = k:lower():gsub("%s+", "")
                if str5 == str then return settings2Item == true end
            elseif type(settings2Item) == "table" and settings2Item.Enabled ~= nil then
                local str5 = k:lower():gsub("%s+", "")

                if str5 == str or str5 .. "esp" == str or str5 .. "track" == str then
                    return settings2Item.Enabled == true
                end
            end
        end

        return nil
    end

    function createOrUpdateMobileFloatingButton(value, str)
        if not lastIsMobile then return end
        local playerGui = guiParent or localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
        if not playerGui then return end
        local mobileHUD = playerGui:FindFirstChild("VD_MobileHUD")

