    function cleanupParryUI()
        pcall(function()
            local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
            if not playerGui then return end

            for _, name in ipairs({"Survivor", "Survivor-con", "Survivor-mob", "Survivor-gamepad"}) do
                local instance2 = playerGui:FindFirstChild(name)

                if instance2 then
                    local bottomLeft = instance2:FindFirstChild("bottom left")
                        or instance2:FindFirstChild("BottomLeft")
                        or instance2

                    local gen = bottomLeft:FindFirstChild("Gen") or instance2:FindFirstChild("Gen", true)
                    local itemFrame = gen and gen:FindFirstChild("ItemFrame")

                    if itemFrame then
                        local gui = itemFrame:FindFirstChild("Gui")

                        if gui then
                            local parryCooldownLabel = gui:FindFirstChild("ParryCooldownLabel")

                            if parryCooldownLabel then
                                pcall(function()
                                    parryCooldownLabel:Destroy()
                                end)
                            end
                        end

                        local parryCooldownLabel = itemFrame:FindFirstChild("ParryCooldownLabel")

                        if parryCooldownLabel then
                            pcall(function()
                                parryCooldownLabel:Destroy()
                            end)
                        end
                    end
                end
            end

            local instance2 = playerGui:FindFirstChild("Survivor-mob")
            local controls = instance2 and instance2:FindFirstChild("Controls")

            if controls then
                local parryCooldownLabel = controls:FindFirstChild("ParryCooldownLabel")

                if parryCooldownLabel then
                    pcall(function()
                        parryCooldownLabel:Destroy()
                    end)
                end

                local instance3 = controls:FindFirstChild("Gui-mob")

                if instance3 and instance3:FindFirstChild("ParryCooldownLabel") then
                    pcall(function()
                        instance3.ParryCooldownLabel:Destroy()
                    end)
                end

                local action = controls:FindFirstChild("action")

                if action and action:FindFirstChild("ParryCooldownLabel") then
                    pcall(function()
                        action.ParryCooldownLabel:Destroy()
                    end)
                end
            end
        end)
    end

    do
        local list10 = {}
