                targetY = targetY + (list11Item.height or 46) + num5
            end
        end

        local callback6

        callback6 = function()
            if #list11 >= num4 or #list10 == 0 then return end
            local v5 = table.remove(list10, 1)
            local count = #list10
            local num7 = 3

            if count > 0 then
                num7 = math.max(1.2, 3 - count * 0.4)
            end

            local str = tostring(v5.notifType or "info"):lower()
            local str5 = "i"
            local text = UI.Text
            local stroke = UI.Stroke

            if str == "warning" or str == "warn" then
                str5 = "!"
                text = UI.Warning
                stroke = Color3.fromRGB(56, 40, 20)
            elseif str == "error" or str == "danger" then
                str5 = "✕"
                text = UI.Danger
                stroke = Color3.fromRGB(60, 24, 28)
            elseif str == "success" then
                str5 = "✓"
                text = UI.Success
                stroke = Color3.fromRGB(24, 52, 32)
            else
                str5 = "i"
                text = UI.AccentCyan
                stroke = UI.Stroke
            end

            local jlxHelperGui = screenGui or localPlayer
                and localPlayer:FindFirstChildOfClass("PlayerGui")
                and localPlayer.PlayerGui:FindFirstChild("JLXHelperGui")

            if not jlxHelperGui then return end

            local function fnByte(value)
                if not value then return "" end
                local str6 = tostring(value)
                str6 = str6:gsub("", ""):gsub("", ""):gsub("⚡", ""):gsub("⏻", ""):gsub("👥", ""):gsub("📩", ""):gsub("⚔\239\184\143", ""):gsub("⚔", ""):gsub("▶", ""):gsub("◐", ""):gsub("📄", ""):gsub("◎", "")

                str6 = str6:gsub("[%z\001-\127\194-\244][\128-\191]*", function(arg1)
                    local v6 = string.byte(arg1, 1)
                    if v6 >= 240 then return "" end
                    return arg1
                end)

                str6 = str6:gsub("%s+", " "):gsub("^%s*(.-)%s*$", "%1")
                return str6
            end

            local text2 = fnByte(v5.title or "Warning")
            local str6 = fnByte(v5.message or "")
            local str7 = str6

            if not str7:find("<font") then
                str7 = str7:gsub("ADMIN", "<font color='#ef4444'><b>ADMIN</b></font>")
                str7 = str7:gsub("MODERATOR", "<font color='#3b82f6'><b>MODERATOR</b></font>")
