            if settings2.DisableAllNotifications then
                clearAllNotifications()
                return
            end

            table.insert(list10, {title = title, message = message, notifType = notifType or "info"})

            while #list11 < num4 and #list10 > 0 do
                callback6()
            end
        end
    end

    function showStartupCapabilityReport()
        local unavailableFeatures = getUnavailableFeatures()

        if #unavailableFeatures == 0 then
            showNotification(
                "Compatibility Check",
                "All features supported on " .. fnIdentifyExecutor() .. ".",
                "success"
            )

            return
        end

        local str = table.concat(unavailableFeatures, ", ")

        if #str > 90 then
            str = str:sub(1, 87) .. "..."
        end

        showNotification(
            "Compatibility Warning",
            #unavailableFeatures .. " feature group(s) may not work: " .. str,
            "warning"
        )
    end

