    function findEmoteByName(settings2Item)
        if not settings2Item then return nil end

        for _, v in ipairs(allEmotesList or {}) do
            if v.name == settings2Item or v.name:lower() == settings2Item:lower() then return v end
        end

        for _, userCustomEmote in ipairs(settings2.UserCustomEmotes or {}) do
            if userCustomEmote.name == settings2Item or userCustomEmote.name:lower() == settings2Item:lower() then
                return userCustomEmote
            end
        end

        return nil
    end

    function getFullEmoteList()
        local list10 = {}

        for _, value in ipairs(allEmotesList or {}) do
            table.insert(list10, value)
        end

        for _, userCustomEmote in ipairs(settings2.UserCustomEmotes or {}) do
            table.insert(list10, userCustomEmote)
        end

        return list10
    end

