    applyCustomBg = function()
        local sidebar = mainFrame:FindFirstChild("Sidebar")

        local enabled = isPremiumActive()
            and map
            and (map.CustomBackground or map["Custom Background"])
            and settings2.CustomBackground
            and settings2.CustomBackground.Enabled

        if not enabled then
            imageLabel.Visible = false
            frame.Visible = false
            mainFrame.BackgroundColor3 = UI.Bg
            mainFrame.BackgroundTransparency = themes and themes[currentThemeName] and themes[currentThemeName].BgTrans or 0.02

            if sidebar then
                sidebar.BackgroundTransparency = 0.05
            end

            return
        end

        local customBackground = settings2.CustomBackground
        local image = ""

        if customBackground.LocalFile and customBackground.LocalFile ~= "" then
            local v5 = writefile and readfile and isfile and v1

            if v5 then
                local success2, result2 = pcall(v1, customBackground.LocalFile)

                if success2 and result2 and result2 ~= "" then
                    image = result2
                end
            end
        end

        if image == "" and customBackground.AssetId and customBackground.AssetId ~= "" then
            local assetId = customBackground.AssetId

            if not assetId:match("^rbxassetid://") then
                assetId = "rbxassetid://" .. (assetId:match("%d+") or "")
            end

            image = assetId
        end

        if image == "" then
            imageLabel.Visible = false
            frame.Visible = false
            mainFrame.BackgroundColor3 = UI.Bg
            mainFrame.BackgroundTransparency = themes and themes[currentThemeName] and themes[currentThemeName].BgTrans or 0.02

            if sidebar then
                sidebar.BackgroundTransparency = 0.05
            end

            return
        end

        imageLabel.Image = image
        imageLabel.ImageColor3 = Color3.fromRGB(255, 255, 255)

        if customBackground.ScaleType then
            local crop = Enum.ScaleType.Crop

            if customBackground.ScaleType == "Stretch" then
                crop = Enum.ScaleType.Stretch
            elseif customBackground.ScaleType == "Fit" then
                crop = Enum.ScaleType.Fit
            end

            imageLabel.ScaleType = crop
        end

        imageLabel.Visible = true
        local num4 = math.clamp((customBackground.Overlay or 40) / 100, 0, 0.7)
        frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        frame.BackgroundTransparency = 1 - num4
        frame.Visible = num4 > 0
        mainFrame.BackgroundTransparency = 1

        if sidebar then
            sidebar.BackgroundTransparency = 0.85
        end
    end

