    registerConnection(RunService.RenderStepped:Connect(function()
        local flag12 = true

        pcall(function()
            flag12 = UserInputService:IsWindowFocused()
        end)

        if not flag12 then return end

        if mainFrame and flag11 or isEmoteWheelOpen then
            pcall(function()
                local mouse = localPlayer:GetMouse()

                if mouse and mouse.Icon ~= "rbxassetid://26140499" then
                    mouse.Icon = "rbxassetid://26140499"
                end

                if UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
                    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                end

                if not UserInputService.MouseIconEnabled then
                    UserInputService.MouseIconEnabled = true
                end
            end)
        else
            pcall(function()
                local camera2 = workspace.CurrentCamera
                if camera2 and camera2.CameraType == Enum.CameraType.Scriptable then return end
                local team = localPlayer.Team

                local foundIndex = not team
                    or team.Name == "Spectators"
                    or team.Name:lower():find("spec")
                    or team.Name:lower():find("lobby")

                local character = localPlayer.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                local flag13 = humanoid and humanoid.Health > 0
                local lastIsMobile2 = lastIsMobile or UserInputService.TouchEnabled

                if not lastIsMobile2 and not foundIndex and flag13 then
                    if UserInputService.MouseBehavior ~= Enum.MouseBehavior.LockCenter
                        or UserInputService.MouseIconEnabled ~= false then
                        UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
                        UserInputService.MouseIconEnabled = false
                    end
                else
                    if UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter
                        or UserInputService.MouseIconEnabled ~= true then
                        UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                        UserInputService.MouseIconEnabled = true
                    end
                end
            end)
        end

        pcall(function()
            local camera2 = workspace.CurrentCamera
            if not camera2 or camera2.CameraType == Enum.CameraType.Scriptable then return end
            local replicatedStorage = game:GetService("ReplicatedStorage")

            if replicatedStorage:GetAttribute("RankedState") == "Intro"
                or replicatedStorage:GetAttribute("Darkness2Covered") == true then
                return
            end

            local localKiller = isLocalKiller()

            if localKiller then
                if settings2.KillerThirdPerson then
                    localPlayer.CameraMode = Enum.CameraMode.Classic
                    localPlayer.CameraMinZoomDistance = 10

                    if settings2.InfiniteZoom then
