    function switchTab(tabNameFromInstance)
        if activeTab == tabNameFromInstance and (not searchContainer or not searchContainer.Visible) then
            if tabContainers
                and tabContainers[tabNameFromInstance]
                and not tabContainers[tabNameFromInstance].Visible then
                tabContainers[tabNameFromInstance].Visible = true
                tabContainers[tabNameFromInstance].GroupTransparency = 0
            end

            return
        end

        if searchContainer then
            searchContainer.Visible = false
        end

        if searchBox and searchBox.Text ~= "" then
            searchBox.Text = ""

            if clearSearchBtn then
                clearSearchBtn.Visible = false
            end
        end

        for k, instance2 in pairs(tabButtons) do
            local icon = instance2:FindFirstChild("Icon")
            local activeIndicator = instance2:FindFirstChild("ActiveIndicator")
            local uiStroke = instance2:FindFirstChildOfClass("UIStroke")

            if k == tabNameFromInstance then
                TweenService:Create(
                    instance2,
                    TweenInfo.new(0.18),
                    {BackgroundColor3 = Color3.fromRGB(18, 20, 26), BackgroundTransparency = 0.1}
                ):Play()

                if uiStroke then
                    TweenService:Create(
                        uiStroke,
                        TweenInfo.new(0.18),
                        {Transparency = 0, Color = Color3.fromRGB(255, 255, 255)}
                    ):Play()
                end

                if icon then
                    TweenService:Create(
                        icon,
                        TweenInfo.new(0.18),
                        {ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 0}
                    ):Play()
                end

                if activeIndicator then
                    TweenService:Create(
                        activeIndicator,
                        TweenInfo.new(0.18),
                        {BackgroundTransparency = 0, Size = UDim2.new(0, 3, 0.7, 0)}
                    ):Play()
                end
            else
                TweenService:Create(
                    instance2,
                    TweenInfo.new(0.18),
                    {BackgroundColor3 = Color3.fromRGB(15, 16, 21), BackgroundTransparency = 1}
                ):Play()

                if uiStroke then
                    TweenService:Create(uiStroke, TweenInfo.new(0.18), {Transparency = 1}):Play()
                end

                if icon then
                    TweenService:Create(
                        icon,
                        TweenInfo.new(0.18),
                        {ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 0.35}
                    ):Play()
                end

                if activeIndicator then
                    TweenService:Create(
                        activeIndicator,
                        TweenInfo.new(0.18),
                        {BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0.7, 0)}
                    ):Play()
                end
            end
        end

        for k, v in pairs(tabContainers) do
            if k == tabNameFromInstance then
                v.Visible = true
                v.GroupTransparency = 1
                TweenService:Create(v, TweenInfo.new(0.2), {GroupTransparency = 0}):Play()
            else
                v.Visible = false
            end
        end

        activeTab = tabNameFromInstance

        if tabNameFromInstance == "Teleport" or tabNameFromInstance == "TP" then
            if scanMapObjects then
                pcall(scanMapObjects)
            end

            if refreshTPMenu then
                pcall(refreshTPMenu)
            end
        end
    end

    local function getStr(value)
        if not value then return "" end
        return tostring(value):gsub("<[^>]+>", ""):gsub("%s*%+", ""):gsub("%s*%b()", ""):gsub("^%s*(.-)%s*$", "%1")
    end

    function resolveTabNameFromInstance(parent2)
        local parent = parent2

        while parent and parent ~= contentFolder and parent ~= screenGui and parent ~= game do
            if tabByScroll and tabByScroll[parent] then return tabByScroll[parent] end

            if tabContainers then
                for k, v in pairs(tabContainers) do
                    if parent == v then return k end
                end
            end

            if groupInfoByContent and groupInfoByContent[parent] and groupInfoByContent[parent].parentTab then
                return groupInfoByContent[parent].parentTab
            end

            parent = parent.Parent
        end

        return nil
    end

    function registerSearchableFeature(arg1)
        if not arg1 or not arg1.name or arg1.name == "" then return end
        local str = getStr(arg1.name)
        if str == "" or str:lower() == "trigger" then return end
        local tabNameFromInstance = nil

        if arg1.container then
            tabNameFromInstance = resolveTabNameFromInstance(arg1.container)
        end

        if not tabNameFromInstance and arg1.parent then
            tabNameFromInstance = resolveTabNameFromInstance(arg1.parent)
        end

        local tabName = arg1.tabName or tabNameFromInstance or currentBuildingTabName or "Home"
        local sectionName = arg1.sectionName or currentBuildingSectionName or "General"

        local value = {
            name = str,
            rawLabel = arg1.name,
            tabName = tabName,
            sectionName = sectionName,
            controlType = arg1.controlType or "Toggle",
            container = arg1.container,
            parent = arg1.parent,
            parentGroup = arg1.parentGroup,
            isPremium = arg1.isPremium or fn2(arg1.name),
            keybindName = arg1.keybindName,
            controlRef = arg1.controlRef,
            callback = arg1.callback,
            description = arg1.description or "",
        }

        table.insert(searchableFeatures, value)
        return value
    end

    function jumpToFeature(feat)
        if not feat then return end

        if searchBox then
            searchBox.Text = ""
            searchBox:ReleaseFocus()
        end

        if clearSearchBtn then
            clearSearchBtn.Visible = false
        end

        if searchContainer then
            searchContainer.Visible = false
        end

        local container = feat.container or feat.parentGroup and feat.parentGroup.container
        local tabNameFromInstance = nil

        if container then
            tabNameFromInstance = resolveTabNameFromInstance(container)
        end

        if not tabNameFromInstance and feat.parent then
            tabNameFromInstance = resolveTabNameFromInstance(feat.parent)
        end

        if not tabNameFromInstance then
            tabNameFromInstance = feat.tabName
        end

        local map10 = {
            dashboard = "Home",
            home = "Home",
            esp = "ESP",
            farm = "Farm",
            autofarm = "Farm",
            self = "Self",
            modifiers = "Self",
            combat = "Combat",
            tp = "Teleport",
            teleport = "Teleport",
            teleports = "Teleport",
            visual = "Visuals",
            visuals = "Visuals",
            config = "Config",
            configs = "Config",
            community = "Community",
        }

        if tabNameFromInstance then
            local str = tostring(tabNameFromInstance):lower():gsub("%s+", "")

            if map10[str] then
                tabNameFromInstance = map10[str]
            end
        end

        if not (tabNameFromInstance and tabContainers and tabContainers[tabNameFromInstance]) then
            for k, _ in pairs(tabContainers or {}) do
                if k:lower() == tostring(tabNameFromInstance):lower() then
                    tabNameFromInstance = k
                    break
                end
            end
        end

        if not (tabNameFromInstance and tabContainers and tabContainers[tabNameFromInstance]) then
            tabNameFromInstance = activeTab or "Home"
        end

        if activeTab == tabNameFromInstance then
            if tabContainers and tabContainers[tabNameFromInstance] then
                tabContainers[tabNameFromInstance].Visible = true
                tabContainers[tabNameFromInstance].GroupTransparency = 0
            end
        else
            switchTab(tabNameFromInstance)
        end

        if container then
            local container2 = container

            while container2 and container2 ~= contentFolder and container2 ~= screenGui and container2 ~= game do
                if groupInfoByContent
                    and groupInfoByContent[container2]
                    and groupInfoByContent[container2].groupObj
                    and groupInfoByContent[container2].groupObj.toggleExpand then
                    pcall(function()
                        groupInfoByContent[container2].groupObj.toggleExpand(true)
                    end)
                end

                container2 = container2.Parent
            end
        end

        if feat.parentGroup and feat.parentGroup.toggleExpand then
            pcall(function()
                feat.parentGroup.toggleExpand(true)
            end)
        end

        task.spawn(function()
            task.wait(0.12)
            local v5 = tabScrollByName and (tabScrollByName[tabNameFromInstance] or tabScrollByName[feat.tabName])

            if v5 and container and container:IsDescendantOf(v5) then
                pcall(function()
                    local v6 = v5.AbsolutePosition.Y
                    local v7 = container.AbsolutePosition.Y
                    local v8 = v5.CanvasPosition.Y
                    local b = v8 + (v7 - v6) - 50
                    v5.CanvasPosition = Vector2.new(0, math.max(0, b))
                end)
            end

            if container and container.Parent and container.Parent:IsA("ScrollingFrame") then
                local parent = container.Parent

                pcall(function()
                    local v6 = parent.AbsolutePosition.Y
                    local v7 = container.AbsolutePosition.Y
                    local v8 = parent.CanvasPosition.Y
                    local b = v8 + (v7 - v6) - 20
                    parent.CanvasPosition = Vector2.new(0, math.max(0, b))
                end)
            end

            if container then
                pcall(function()
                    local uiStroke = container:FindFirstChildOfClass("UIStroke") or container:FindFirstChild("VisualFrame")
                        and container.VisualFrame:FindFirstChildOfClass("UIStroke") or container:FindFirstChildWhichIsA("Frame")
                        and container:FindFirstChildWhichIsA("Frame"):FindFirstChildOfClass("UIStroke")

                    if uiStroke then
                        local color = uiStroke.Color
                        local thickness = uiStroke.Thickness
                        uiStroke.Color = UI.AccentCyan or UI.Accent
                        uiStroke.Thickness = 2.2

                        TweenService:Create(
                            uiStroke,
                            TweenInfo.new(1.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                            {Color = color, Thickness = thickness}
                        ):Play()
                    end
                end)
            end
        end)
    end

