    function updateSearchResults(list10)
        for _, instance2 in ipairs(renderedResultCards) do
            if instance2 and instance2.Parent then
                instance2:Destroy()
            end
        end

        renderedResultCards = {}

        if not list10 or list10 == "" then
            if searchSubLbl then
                searchSubLbl.Text = "Type in the search bar above to filter features across all tabs."
            end

            return
        end

        local list11 = {}
        local map10 = {}

        for _, feat in ipairs(searchableFeatures) do
            local str = feat.name:lower()
            local str5 = (feat.sectionName or ""):lower()
            local str6 = (feat.tabName or ""):lower()
            local str7 = (feat.keybindName or ""):lower()
            local str8 = (feat.description or ""):lower()
            local score = nil

            if str == list10 then
                score = 1
            elseif str:sub(1, #list10) == list10 then
                score = 2
            elseif str:find(list10, 1, true) then
                score = 3
            elseif str5:find(list10, 1, true) then
                score = 4
            elseif str6:find(list10, 1, true) then
                score = 5
            elseif str7:find(list10, 1, true) or str8:find(list10, 1, true) then
                score = 6
            end

            if score and not map10[feat.name .. ":" .. (feat.tabName or "")] then
                map10[feat.name .. ":" .. (feat.tabName or "")] = true
                table.insert(list11, {feat = feat, score = score})
            end
        end

        table.sort(list11, function(arg1, arg2)
            if arg1.score ~= arg2.score then return arg1.score < arg2.score end
            return arg1.feat.name < arg2.feat.name
        end)

        if searchSubLbl then
            searchSubLbl.Text = string.format("Found %d feature(s) matching \"%s\"", #list11, list10)
