    function resolveIcon(arg1, arg2)
        if map10[arg1] then return map10[arg1] end
        local getcustomasset2 = v1 or syn and syn.getcustomasset

        if getcustomasset2 and writefile and isfile and readfile then
            local str5 = "VD_Icons"

            if not isfolder or not isfolder(str5) then
                pcall(makefolder, str5)
            end

            local str6 = str5 .. "/" .. arg1 .. ".png"

            if isfile(str6) then
                local success2, result2 = pcall(getcustomasset2, str6)

                if success2 and result2 then
                    map10[arg1] = result2
                    return result2
                end
            else
                task.spawn(function()
                    pcall(function()
                        local str7 = "https://raw.githubusercontent.com/latte-soft/lucide-roblox/master/icons/compiled/48px/" ..
                            arg1 ..
                            ".png"

                        local response = game:HttpGet(str7)

                        if response and #response > 50 then
                            writefile(str6, response)
                        end
                    end)
                end)
            end
        end

        map10[arg1] = arg2
        return arg2
    end

