    function toggleUI(arg1)
        if not mainFrame then return end
        if flag5 then return end
        if toggleInProgress then return end
        local flag12 = arg1 ~= nil and arg1 or not mainFrame.Visible

        if textButton then
            textButton.Visible = lastIsMobile or UserInputService.TouchEnabled
        end

        mainFrame.ClipsDescendants = true
        local default = themes[currentThemeName] or themes.Default
        local mouse = localPlayer:GetMouse()

        if flag12 then
            fnMouseBehavior()
            toggleInProgress = true
            flag11 = true
            mainFrame.Visible = true

            pcall(function()
                local modalButton = mainFrame:FindFirstChild("ModalButton")

                if modalButton then
                    modalButton.Modal = false
                end

                mouse.Icon = "rbxassetid://26140499"
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                UserInputService.MouseIconEnabled = true
            end)

            mainFrame.Size = UDim2.new(0, UI.MainW * 0.85, 0, UI.MainH * 0.85)
            mainFrame.Position = UDim2.new(0.5, -(UI.MainW * 0.85) / 2, 0.5, -(UI.MainH * 0.85) / 2)
            mainFrame.BackgroundTransparency = 1

            local tween = TweenService:Create(mainFrame, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                Size = UDim2.new(0, UI.MainW, 0, UI.MainH),
                Position = UDim2.new(0.5, -UI.MainW / 2, 0.5, -UI.MainH / 2),
            })

            local v5 = settings2.CustomBackground
                and settings2.CustomBackground.Enabled
                and isPremiumActive()
                and map
                and (map.CustomBackground or map["Custom Background"])
                and imageLabel
                and imageLabel.Visible

            local bgTrans = v5 and 1 or default.BgTrans

            local tween2 = TweenService:Create(
                mainFrame,
                TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                {BackgroundTransparency = bgTrans}
            )

            tween:Play()
            tween2:Play()

            tween.Completed:Connect(function()
                toggleInProgress = false
            end)
        else
            toggleInProgress = true
            flag11 = false

            pcall(function()
                local modalButton = mainFrame:FindFirstChild("ModalButton")

                if modalButton then
                    modalButton.Modal = false
                end

                fnMouseBehavior2()
            end)

            local tween = TweenService:Create(mainFrame, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                Size = UDim2.new(0, UI.MainW * 0.85, 0, UI.MainH * 0.85),
                Position = UDim2.new(0.5, -(UI.MainW * 0.85) / 2, 0.5, -(UI.MainH * 0.85) / 2),
            })

            local tween2 = TweenService:Create(
                mainFrame,
                TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
                {BackgroundTransparency = 1}
            )

            tween:Play()
            tween2:Play()

            tween.Completed:Connect(function()
                mainFrame.Visible = false
                toggleInProgress = false
            end)
        end
    end

    local function fn8(value)
        if not value or value == "" or value == "None" then return "None" end
        local str = tostring(value)
