                        fnCancel()
                        settings2.Keybinds[keybindName] = "None"
                        pcall(saveSettings)
                        fnFromRGB2(true)

                        if _G.VD_RefreshHotkeys then
                            pcall(_G.VD_RefreshHotkeys)
                        end

                        return
                    end

                    if not str then
                        str = name
                        now = tick()
                        textButton2.Text = str:upper()

                        v5 = task.spawn(function()
                            task.wait(0.4)

                            if str == name and isBindingKey then
                                textButton2.Text = "HOLD " .. str:upper()

                                TweenService:Create(
                                    uiStroke,
                                    TweenInfo.new(0.15),
