                                ):Play()

                                textButton2.TextColor3 = UI.AccentPink or Color3.fromRGB(255, 60, 120)
                            end
                        end)
                    end
                end
            end)

            connection7 = UserInputService.InputEnded:Connect(function(input)
                local flag12 = input.UserInputType == Enum.UserInputType.Gamepad1
                    or input.UserInputType == Enum.UserInputType.Gamepad2
                    or input.UserInputType == Enum.UserInputType.Gamepad3
                    or input.UserInputType == Enum.UserInputType.Gamepad4

                local flag13 = input.UserInputType == Enum.UserInputType.Keyboard or flag12
                local flag14 = input.UserInputType == Enum.UserInputType.MouseButton3

                if (flag13 or flag14) and str then
                    local name = flag13 and input.KeyCode.Name or input.UserInputType.Name

                    if name == str then
                        local num4 = tick() - now
