                        end

                        pcall(saveSettings)
                        fnFromRGB2(true)

                        if _G.VD_RefreshHotkeys then
                            pcall(_G.VD_RefreshHotkeys)
                        end
                    end
                end
            end)
        end)

        fnFromRGB2(false)
