    function setRevolverAutofarm(revolverAutofarm)
        if revolverAutofarm and not isPremiumActive("RevolverAutofarm") then
            showNotification("Premium Feature +", "Unlock the Premium version to use this feature!", "warning")

            if controlRegistry.RevolverAutofarm and controlRegistry.RevolverAutofarm.setValue then
                pcall(function()
                    controlRegistry.RevolverAutofarm.setValue(false)
                end)
            end

            return
        end

        settings2.RevolverAutofarm = revolverAutofarm

        if revolverAutofarm then
            if not settings2.InstantHeal then
                instantHealWasDisabledBeforeRevolver = true
                settings2.InstantHeal = true

                if controlRegistry.InstantHeal and controlRegistry.InstantHeal.setValue then
                    pcall(function()
                        controlRegistry.InstantHeal.setValue(true)
                    end)
                end
            else
                instantHealWasDisabledBeforeRevolver = false
            end
        else
            if instantHealWasDisabledBeforeRevolver then
                settings2.InstantHeal = false

                if controlRegistry.InstantHeal and controlRegistry.InstantHeal.setValue then
                    pcall(function()
                        controlRegistry.InstantHeal.setValue(false)
                    end)
                end

                instantHealWasDisabledBeforeRevolver = false
            end
        end

        if controlRegistry.RevolverAutofarm and controlRegistry.RevolverAutofarm.setValue then
            pcall(function()
                controlRegistry.RevolverAutofarm.setValue(revolverAutofarm)
            end)
        end

        pcall(saveSettings)
    end

