        local function fn9(value)
            if not value then return nil end
            value = tostring(value):gsub("^%s+", ""):gsub("%s+$", "")
            if value == "" then return nil end
            local num4 = tonumber(value)
            if num4 and num4 > 0 then return num4 end

            local success2, result2 = pcall(function()
                return Players:GetUserIdFromNameAsync(value)
            end)

            if success2 and result2 then return result2 end
            return nil
        end

        _G.VD_GetTargetPlayers = function(arg1)
            arg1 = arg1
                or settings2 and settings2.PlayerCustomizer and settings2.PlayerCustomizer.SelectedTarget
                or "LocalPlayer (Self)"

            local list11 = {}

            if arg1 == "LocalPlayer (Self)" or arg1 == "Self" then
                if localPlayer then
                    table.insert(list11, localPlayer)
                end
            elseif arg1 == "All Players" then
                for _, player in ipairs(Players:GetPlayers()) do
                    table.insert(list11, player)
                end
            elseif arg1 == "Killer" then
                for _, player in ipairs(Players:GetPlayers()) do
                    local player2 = ActiveESP and ActiveESP.Players and ActiveESP.Players[player]
                    local isKiller = player2 and player2.IsKiller or player.Team and player.Team.Name == "Killer"

                    if isKiller then
                        table.insert(list11, player)
                    end
                end
            elseif arg1 == "Survivors" then
                for _, player in ipairs(Players:GetPlayers()) do
                    local player2 = ActiveESP and ActiveESP.Players and ActiveESP.Players[player]
                    local isSurvivor = player2 and player2.IsSurvivor or player.Team and player.Team.Name == "Survivors"

                    if isSurvivor and player ~= localPlayer then
                        table.insert(list11, player)
                    end
                end
            else
                for _, player in ipairs(Players:GetPlayers()) do
                    if player.Name == arg1 or player.DisplayName == arg1 or tostring(player.UserId) == arg1 then
                        table.insert(list11, player)
                        break
                    end
                end
            end

            return list11
        end

        _G.VD_GetLobbyPlayerOptions = function()
            local list11 = {"LocalPlayer (Self)", "All Players", "Killer", "Survivors"}
            local list12 = {"LocalPlayer (Self)", "All Players", "Killer", "Survivors"}

            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= localPlayer then
                    local str = string.format("%s (@%s)", player.DisplayName or player.Name, player.Name)
                    table.insert(list11, str)
                    table.insert(list12, player.Name)
                end
            end

            return list11, list12
        end

        _G.VD_UpdateCustomParticles = function()
            pcall(function()
                local customParticles = settings2.CustomParticles

                if not customParticles or not customParticles.Enabled then
                    for _, player in ipairs(Players:GetPlayers()) do
                        if player.Character then
                            for _, descendant in ipairs(player.Character:GetDescendants()) do
                                if descendant.Name == "VD_CustomParticleEmitter"
                                    or descendant.Name == "VD_CustomParticleAttachment" then
                                    pcall(function()
                                        descendant:Destroy()
                                    end)
                                end
                            end
                        end
                    end

                    return
                end

                local list11 = _G.VD_GetTargetPlayers(customParticles.Target)
                local map11 = {}

                for _, list11Item in ipairs(list11) do
                    map11[list11Item] = true
                end

                for _, player in ipairs(Players:GetPlayers()) do
                    if not map11[player] and player.Character then
                        for _, descendant in ipairs(player.Character:GetDescendants()) do
                            if descendant.Name == "VD_CustomParticleEmitter"
                                or descendant.Name == "VD_CustomParticleAttachment" then
                                pcall(function()
                                    descendant:Destroy()
                                end)
                            end
                        end
                    end
                end

                local hellfire = _G.VD_PARTICLE_PRESETS.Hellfire
                local color = customParticles.Color or Color3.fromRGB(255, 255, 255)
                local rate = customParticles.Rate or 25
                local size = customParticles.Size or 1

                for _, list11Item in ipairs(list11) do
                    local character = list11Item.Character

                    if character then
                        local humanoidRootPart2 = character:FindFirstChild("HumanoidRootPart")
                            or character:FindFirstChild("Torso")
                            or character:FindFirstChild("UpperTorso")

                        if humanoidRootPart2 then
                            local customParticleAttachment = humanoidRootPart2:FindFirstChild("VD_CustomParticleAttachment")

                            if not customParticleAttachment then
                                customParticleAttachment = Instance.new("Attachment")
                                customParticleAttachment.Name = "VD_CustomParticleAttachment"
                                customParticleAttachment.Parent = humanoidRootPart2
                            end

                            local customParticleEmitter = customParticleAttachment:FindFirstChild("VD_CustomParticleEmitter")

                            if not customParticleEmitter then
                                customParticleEmitter = Instance.new("ParticleEmitter")
                                customParticleEmitter.Name = "VD_CustomParticleEmitter"
                                customParticleEmitter.Parent = customParticleAttachment
                            end

                            customParticleEmitter.Texture = hellfire.Texture
                            customParticleEmitter.Rate = rate
                            customParticleEmitter.Size = NumberSequence.new(size * 0.5, size)
                            customParticleEmitter.Lifetime = hellfire.Lifetime or NumberRange.new(1, 2)
                            customParticleEmitter.Speed = hellfire.Speed or NumberRange.new(2, 6)
                            customParticleEmitter.SpreadAngle = hellfire.SpreadAngle or Vector2.new(180, 180)
                            customParticleEmitter.Acceleration = hellfire.Acceleration or Vector3.new(0, 0, 0)
                            customParticleEmitter.LightEmission = hellfire.LightEmission or 0.8
                            customParticleEmitter.LightInfluence = hellfire.LightInfluence or 0

                            if hellfire.Rotation then
                                customParticleEmitter.Rotation = hellfire.Rotation
                            end

                            if hellfire.RotSpeed then
                                customParticleEmitter.RotSpeed = hellfire.RotSpeed
                            end

                            if hellfire.Transparency then
                                customParticleEmitter.Transparency = hellfire.Transparency
                            else
                                customParticleEmitter.Transparency = NumberSequence.new({
                                    NumberSequenceKeypoint.new(0, 0),
                                    NumberSequenceKeypoint.new(0.8, 0.1),
                                    NumberSequenceKeypoint.new(1, 1),
                                })
                            end

                            if not customParticles.Rainbow then
                                customParticleEmitter.Color = ColorSequence.new(color)
                            end

                            customParticleEmitter.Enabled = true
                        end
                    end
                end
            end)
