        local function fnBodyColors(result3, parent)
            if not parent or not result3 then return end
            fnAccessory(parent)
            local head = parent:FindFirstChild("Head")

            if result3.bodyColors then
                local bodyColors = Instance.new("BodyColors")
                bodyColors.HeadColor3 = Color3.fromHex(result3.bodyColors.headColorHex or "f5cd92")
                bodyColors.LeftArmColor3 = Color3.fromHex(result3.bodyColors.leftArmColorHex or "f5cd92")
                bodyColors.RightArmColor3 = Color3.fromHex(result3.bodyColors.rightArmColorHex or "f5cd92")
                bodyColors.LeftLegColor3 = Color3.fromHex(result3.bodyColors.leftLegColorHex or "f5cd92")
                bodyColors.RightLegColor3 = Color3.fromHex(result3.bodyColors.rightLegColorHex or "f5cd92")
                bodyColors.TorsoColor3 = Color3.fromHex(result3.bodyColors.torsoColorHex or "f5cd92")
                bodyColors.Parent = parent
            end

            if result3.assets then
                for _, asset in ipairs(result3.assets) do
                    local id = asset.id

                    task.spawn(function()
                        pcall(function()
                            local list11 = game:GetObjects("rbxassetid://" .. tostring(id))

                            for _, list11Item in ipairs(list11) do
                                if list11Item:IsA("Accessory") then
                                    list11Item.Parent = parent
                                    local handle = list11Item:FindFirstChild("Handle")

                                    if handle then
                                        local attachment = handle:FindFirstChildOfClass("Attachment")

                                        if attachment then
                                            local part = nil

                                            for _, child in ipairs(parent:GetChildren()) do
                                                if child:IsA("BasePart") then
                                                    part = child:FindFirstChild(attachment.Name)

                                                    if part then
                                                        local weld = Instance.new("Weld")
                                                        weld.Name = "AccessoryWeld"
                                                        weld.Part0 = handle
                                                        weld.Part1 = child
                                                        weld.C0 = attachment.CFrame
                                                        weld.C1 = part.CFrame
                                                        weld.Parent = handle
                                                        break
                                                    end
                                                end
                                            end
                                        elseif head then
                                            local weld = Instance.new("Weld")
                                            weld.Name = "AccessoryWeld"
                                            weld.Part0 = handle
                                            weld.Part1 = head
                                            weld.C0 = CFrame.new(0, 0.5, 0)
                                            weld.Parent = handle
                                        end

                                        handle.CanCollide = false
                                    end
                                elseif list11Item:IsA("Shirt")
                                    or list11Item:IsA("Pants")
                                    or list11Item:IsA("ShirtGraphic")
                                    or list11Item:IsA("BodyColors")
                                    or list11Item:IsA("CharacterMesh") then
                                    list11Item.Parent = parent
                                elseif list11Item:IsA("Decal") and head then
                                    list11Item.Name = "face"
                                    list11Item.Parent = head
                                elseif list11Item:IsA("SpecialMesh") and head then
                                    local specialMesh = head:FindFirstChildOfClass("SpecialMesh")

                                    if specialMesh then
                                        specialMesh:Destroy()
                                    end

                                    list11Item.Parent = head
                                end
                            end
                        end)
                    end)
                end
            end
        end

        local function fnPart0(instance2, parent)
            if not parent or not instance2 then return end
            fnAccessory(parent)
            local head = parent:FindFirstChild("Head")

            for _, child in ipairs(instance2:GetChildren()) do
                if child:IsA("Accessory") then
                    local clone = child:Clone()
                    clone.Parent = parent
                    local handle = clone:FindFirstChild("Handle")

                    if handle then
                        local attachment = handle:FindFirstChildOfClass("Attachment")

                        if attachment then
                            for _, child2 in ipairs(parent:GetChildren()) do
                                if child2:IsA("BasePart") then
                                    local part = child2:FindFirstChild(attachment.Name)

                                    if part then
                                        local weld = Instance.new("Weld")
                                        weld.Name = "AccessoryWeld"
                                        weld.Part0 = handle
                                        weld.Part1 = child2
                                        weld.C0 = attachment.CFrame
                                        weld.C1 = part.CFrame
                                        weld.Parent = handle
                                        break
                                    end
                                end
                            end
                        elseif head then
                            local weld = Instance.new("Weld")
                            weld.Name = "AccessoryWeld"
                            weld.Part0 = handle
                            weld.Part1 = head
                            weld.C0 = CFrame.new(0, 0.5, 0)
                            weld.Parent = handle
                        end

                        handle.CanCollide = false
                    end
                elseif child:IsA("Shirt")
                    or child:IsA("Pants")
                    or child:IsA("ShirtGraphic")
                    or child:IsA("BodyColors")
                    or child:IsA("CharacterMesh") then
                    child:Clone().Parent = parent
                elseif child:IsA("Decal") and head then
                    local clone = child:Clone()
                    clone.Name = "face"
                    clone.Parent = head
                end
            end
        end

