        _G.VD_UpdateSurvivorHUD = function()
            pcall(function()
                local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
                if not playerGui then return end
                local list11 = {}

                for _, name in ipairs({
                    "Survivor",
                    "Survivor-con",
                    "Survivor-mob",
                    "SurvivorGui",
                    "SpectatorHUD",
                    "SpectatorHUD-con",
                    "SpectatorHUD-mob",
                }) do
                    local instance2 = playerGui:FindFirstChild(name)

                    if instance2 then
                        local bottomLeft = instance2:FindFirstChild("bottom left") or instance2:FindFirstChild("BottomLeft")

                        if bottomLeft then
                            local frame4 = bottomLeft:FindFirstChild("Frame")

                            if frame4 and not table.find(list11, frame4) then
                                table.insert(list11, frame4)
                            end
                        end

                        local frame4 = instance2:FindFirstChild("Frame", true)

                        if frame4 and (frame4:FindFirstChild("Survivor1") or frame4:FindFirstChild("Survivor2")) then
                            if not table.find(list11, frame4) then
