                for _, list11Item in ipairs(list11) do
                    for _, child in ipairs(list11Item:GetChildren()) do
                        if child:IsA("GuiObject") and (child.Name:sub(1, 8) == "Survivor"
                            or child:FindFirstChildOfClass("TextLabel")
