                                or child:FindFirstChild("ImageLabel", true)
                                or child:FindFirstChild("Avatar", true)
                                or child:FindFirstChild("Icon", true)

                            local viewportFrame = child:FindFirstChild("ViewportFrame")
                                or child:FindFirstChildOfClass("ViewportFrame")
                                or child:FindFirstChild("ViewportFrame", true)

                            local player = nil
