                            if not player and imageLabel2 and imageLabel2.Image then
                                local match = imageLabel2.Image:match("userId=(%d+)") or imageLabel2.Image:match("id=(%d+)")

                                if match then
                                    for _, player2 in ipairs(Players:GetPlayers()) do
                                        if tostring(player2.UserId) == match then
                                            player = player2
                                            break
                                        end
                                    end
                                end
                            end

                            if not player and child.Name == "Survivor1" then
                                player = localPlayer
                            end

                            local spoofedName = nil

                            if player then
                                spoofedName = _G.VD_SpoofedNames
                                    and (_G.VD_SpoofedNames[player.UserId] or _G.VD_SpoofedNames[player.Name])
                            end

                            if (not spoofedName or spoofedName == "")
