                        if spoofedSkin and character and character.Parent then
                            local success2, result2 = pcall(function()
                                return Players:GetCharacterAppearanceAsync(spoofedSkin)
                            end)

                            if success2 and result2 then
                                applyAppearanceFromModel(result2, character)

                                pcall(function()
                                    result2:Destroy()
                                end)
                            end
                        end
                    end)
                end

                if _G.VD_SpoofedNames and _G.VD_SpoofedNames[player.UserId] then
                    task.wait(0.3)

                    pcall(function()
                        local spoofedName = _G.VD_SpoofedNames[player.UserId]
                        local humanoid = character:FindFirstChildOfClass("Humanoid")

                        if humanoid then
                            humanoid.DisplayName = spoofedName
                        end
                    end)
                end

                if settings2.CustomParticles
                    and settings2.CustomParticles.Enabled
                    and _G.VD_UpdateCustomParticles then
                    task.wait(0.5)
                    pcall(_G.VD_UpdateCustomParticles)
                end
            end)
        end

        for _, player in ipairs(Players:GetPlayers()) do
            onPlayerAdded(player)
        end

        Players.PlayerAdded:Connect(onPlayerAdded)
    end)

