    do
        local connection6 = nil

        function stopCustomEmote()
            if connection6 then
                pcall(function()
                    connection6:Disconnect()
                end)

                connection6 = nil
            end

            if currentEmoteTrack then
                pcall(function()
                    currentEmoteTrack:Stop(0.2)
                end)

                currentEmoteTrack = nil
            end

            if currentEmoteSound then
                pcall(function()
                    currentEmoteSound:Stop()
                    currentEmoteSound:Destroy()
                end)

                currentEmoteSound = nil
            end

            pcall(function()
                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                local emoteHandler = remotes and remotes:FindFirstChild("EmoteHandler")

                if emoteHandler then
                    emoteHandler:FireServer("StopEmote")
                end
            end)
        end

        function playCustomEmote(value, value2)
            stopCustomEmote()
            local character = localPlayer and localPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator") or humanoid)

            if not animator then
                showNotification("Animation Player", "Character Animator not found!", "error")
                return
            end

            local match = tostring(value):match("%d+") or tostring(value)
            local animation = Instance.new("Animation")
            animation.AnimationId = "rbxassetid://" .. match

            local success2, result2 = pcall(function()
                return animator:LoadAnimation(animation)
            end)

            if not success2 or not result2 then
                showNotification("Animation Player", "Failed to load emote: " .. tostring(value2), "error")
                return
            end

            currentEmoteTrack = result2
            result2.Priority = Enum.AnimationPriority.Action4
            result2:Play(0.2)

            pcall(function()
                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                local emoteHandler = remotes and remotes:FindFirstChild("EmoteHandler")

                if emoteHandler then
                    emoteHandler:FireServer(value2)
                end
            end)

            showNotification("Animation Player", value2, "info")

            if not (settings2.WalkWhileEmoting == true) then
                connection6 = registerConnection(humanoid:GetPropertyChangedSignal("MoveDirection"):Connect(function()
                    if humanoid.MoveDirection.Magnitude > 0 and currentEmoteTrack == result2 then
                        stopCustomEmote()
                    end
                end))
            end

            result2.Stopped:Connect(function()
                if currentEmoteTrack == result2 then
                    stopCustomEmote()
                end
            end)
        end
    end

