                    if player.Character then
                        for _, child in ipairs(player.Character:GetChildren()) do
                            if (child:IsA("Tool") or child:IsA("Model"))
                                and child.Name ~= "Weapon"
                                and child.Name ~= "Animate"
                                and not child.Name:find("Arm")
                                and not child.Name:find("Body") then
                                equippedItem = child.Name
                                break
                            end
                        end
                    end
                end

                if not equippedItem or equippedItem == "" then return "None" end
                local str5 = "EquippedSkin_" .. equippedItem:gsub(" ", "_")
                local value = player:GetAttribute(str5)

                if not value or value == "Default" or value == "" then
                    local str6 = "EquippedSkin_" .. equippedItem:gsub(" ", "")
                    value = player:GetAttribute(str6)
                end

                if value and value ~= "Default" and value ~= "" then
                    return equippedItem .. " (" .. tostring(value) .. ")"
                end

                return tostring(equippedItem)
            end

