    local function fnAccent()
        _G.VD_FarmStatusLabel = nil
        _G.VD_SetFarmToggle = nil
        _G.VD_SetKillerFarmToggle = nil
        _G.VD_SetTotalAFKToggle = nil
        _G.VD_SetHopEscapeToggle = nil
        _G.VD_SetInstantEscapeToggle = nil
        _G.VD_DoCancelGen = nil

        do
            createSection(tabFarm, "Survivor Automations", UI.Accent)

            local collapsibleToggle = createCollapsibleToggle(tabFarm, "Survivor Auto Farm", settings2.AutoFarmSurvivor, function(autoFarmSurvivor)
                if autoFarmSurvivor then
                    if settings2.AutoFarmAFKTotal then
                        settings2.AutoFarmAFKTotal = false

                        if _G.VD_SetTotalAFKToggle then
                            _G.VD_SetTotalAFKToggle(false)
                        end
                    end

                    if settings2.InstantFinishlineEscape then
                        settings2.InstantFinishlineEscape = false

                        if _G.VD_SetInstantEscapeToggle then
                            _G.VD_SetInstantEscapeToggle(false)
                        end
                    end
                end

                settings2.AutoFarmSurvivor = autoFarmSurvivor

                if autoFarmSurvivor then
                    _G.VD_FarmState.farmTeamStartTime = tick()
                    _G.VD_FarmState.farmLastTeamName = ""
                    _G.VD_AbortPathfinding = false
                    showNotification("Auto Farm Enabled", "Starting automatic generator repairs.", "success")
                else
                    _G.VD_AbortPathfinding = true

                    pcall(function()
                        if not lastIsMobile and VirtualInputManager then
                            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.LeftShift, false, game)
                        end
                    end)

                    local character = localPlayer.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

                    if humanoid then
                        pcall(function()
                            humanoid:Move(Vector3.zero, false)
                            humanoid.WalkSpeed = 16
                        end)
                    end

                    if _G.VD_ExitSubSurfacePocket then
                        pcall(_G.VD_ExitSubSurfacePocket)
                    end

                    showNotification("Auto Farm Disabled", "Stopped survivor autofarm immediately.", "info")
                end

                pcall(saveSettings)
            end, UI.Accent, "AutoFarmSurvivor")

            _G.VD_SetFarmToggle = collapsibleToggle.setValue
            _G.VD_SetFarmToggle = _G.VD_SetFarmToggle
            controlRegistry.AutoFarmSurvivor = collapsibleToggle

            local toggle = createToggle(collapsibleToggle.content, "Unhook Other Survivors", settings2.AutoFarmUnhookSurvivors, function(autoFarmUnhookSurvivors)
                settings2.AutoFarmUnhookSurvivors = autoFarmUnhookSurvivors
                pcall(saveSettings)
            end, UI.Accent, "AutoFarmUnhookSurvivors")

            controlRegistry.AutoFarmUnhookSurvivors = toggle

            local toggle2 = createToggle(collapsibleToggle.content, "Twist Of Fate Evasion", settings2.AutoFarmTwistOfFate, function(autoFarmTwistOfFate)
                settings2.AutoFarmTwistOfFate = autoFarmTwistOfFate
                pcall(saveSettings)
            end, UI.Accent, "AutoFarmTwistOfFate")

            controlRegistry.AutoFarmTwistOfFate = toggle2

            local toggle3 = createToggle(collapsibleToggle.content, "100% Bypass Pathfinding Walk", settings2.AutoFarmPathfinding, function(autoFarmPathfinding)
                settings2.AutoFarmPathfinding = autoFarmPathfinding
                pcall(saveSettings)
            end, UI.Accent, "AutoFarmPathfinding")

            controlRegistry.AutoFarmPathfinding = toggle3

            local toggle4 = createToggle(collapsibleToggle.content, "Ghost Bunker Evasion (Sub-Surface)", settings2.AutoFarmSubSurface, function(autoFarmSubSurface)
                settings2.AutoFarmSubSurface = autoFarmSubSurface
                pcall(saveSettings)
            end, UI.Accent, "AutoFarmSubSurface")

            controlRegistry.AutoFarmSubSurface = toggle4

            local toggle5 = createToggle(tabFarm, "Total AFK Farm (Both Teams)", settings2.AutoFarmAFKTotal, function(autoFarmAFKTotal)
                settings2.AutoFarmAFKTotal = autoFarmAFKTotal

                if autoFarmAFKTotal then
                    _G.VD_FarmState.farmTeamStartTime = tick()
                    _G.VD_FarmState.farmLastTeamName = ""
                    settings2.AutoFarmSurvivor = false

                    if _G.VD_SetFarmToggle then
                        _G.VD_SetFarmToggle(false)
                    end

                    settings2.AutoFarmKiller = false

                    if _G.VD_SetKillerFarmToggle then
                        _G.VD_SetKillerFarmToggle(false)
                    end

                    settings2.InstantFinishlineEscape = false

                    if _G.VD_SetInstantEscapeToggle then
                        _G.VD_SetInstantEscapeToggle(false)
                    end

                    showNotification("Total AFK Farm Enabled", "Coordinating auto farm for both teams.", "success")
                else
                    settings2.AutoFarmSurvivor = false

                    if _G.VD_SetFarmToggle then
                        _G.VD_SetFarmToggle(false)
                    end

                    settings2.AutoFarmKiller = false

                    if _G.VD_SetKillerFarmToggle then
                        _G.VD_SetKillerFarmToggle(false)
                    end

                    settings2.InstantFinishlineEscape = false

                    if _G.VD_SetInstantEscapeToggle then
                        _G.VD_SetInstantEscapeToggle(false)
                    end

                    showNotification("Total AFK Farm Disabled", "Stopped total AFK mode.", "info")
                end

                pcall(saveSettings)
            end, UI.Accent, "TotalAFKFarm")

            _G.VD_SetTotalAFKToggle = toggle5.setValue
            _G.VD_SetTotalAFKToggle = _G.VD_SetTotalAFKToggle
            controlRegistry.AutoFarmAFKTotal = toggle5

            fn3 = function()
                local character = localPlayer.Character
                local humanoidRootPart2 = character and character:FindFirstChild("HumanoidRootPart")

                if not humanoidRootPart2 then
                    showNotification("Escape Failed", "Character root part not found!", "error")
                    return false
                end

                if map and type(map.InstantEscape) == "function" then
                    map.InstantEscape(humanoidRootPart2, showNotification)
                    return true
                else
                    local part = nil
                    local huge = math.huge

                    for _, descendant in ipairs(workspace:GetDescendants()) do
                        if descendant:IsA("BasePart") and (descendant.Name == "Fininshline"
                            or descendant.Name == "Finishline"
                            or descendant.Name:lower():find("finishline")
                            or descendant.Name:lower():find("fininshline")) then
                            local distance = (descendant.Position - humanoidRootPart2.Position).Magnitude

                            if distance < huge then
                                huge = distance
                                part = descendant
                            end
                        end
                    end

                    if part then
                        if _G.VD_StopAllInteractions then
                            pcall(_G.VD_StopAllInteractions)
                            task.wait(0.15)
                        end

                        if settings2.AutoFarmPathfinding and _G.VD_SmartWalkTo then
                            _G.VD_SmartWalkTo(part.Position, 3)
                        else
                            safeSegmentedTeleport(humanoidRootPart2, part.CFrame)
                        end

                        showNotification("Instant Escape", "Teleported to escape line!", "success")
                        return true
                    else
                        showNotification("Instant Escape", "Finish Line not found!", "error")
                        return false
                    end
                end
            end

            local toggle6 = createToggle(tabFarm, "Instant Finishline Escape", settings2.InstantFinishlineEscape, function(instantFinishlineEscape)
                if instantFinishlineEscape then
                    if settings2.AutoFarmSurvivor then
                        settings2.AutoFarmSurvivor = false

                        if _G.VD_SetFarmToggle then
                            _G.VD_SetFarmToggle(false)
                        end
                    end

                    if settings2.AutoFarmAFKTotal then
                        settings2.AutoFarmAFKTotal = false

                        if _G.VD_SetTotalAFKToggle then
                            _G.VD_SetTotalAFKToggle(false)
                        end
                    end

                    if settings2.AutoFarmKiller then
                        settings2.AutoFarmKiller = false

                        if _G.VD_SetKillerFarmToggle then
                            _G.VD_SetKillerFarmToggle(false)
                        end
                    end

                    showNotification(
                        "Instant Escape Enabled",
                        "Will auto escape as soon as survivor match starts.",
                        "success"
                    )
                else
                    showNotification("Instant Escape Disabled", "Instant finishline escape disabled.", "info")
                end

                settings2.InstantFinishlineEscape = instantFinishlineEscape
                pcall(saveSettings)
            end, UI.Accent, "InstantEscape")

            _G.VD_SetInstantEscapeToggle = toggle6.setValue
            controlRegistry.InstantFinishlineEscape = toggle6

            local collapsibleToggle2 = createCollapsibleToggle(tabFarm, "Auto Pumpkin (Crush All)", settings2.AutoPumpkin, function(autoPumpkin)
                settings2.AutoPumpkin = autoPumpkin

                if autoPumpkin then
                    _G.VD_AbortPathfinding = false
                    _G.VD_CurrentFarmState = "RUNNING (Auto Pumpkin)"

                    if _G.VD_UpdateFarmStatus then
                        pcall(function()
                            _G.VD_UpdateFarmStatus("RUNNING (Auto Pumpkin)")
                        end)
                    end

                    showNotification("Auto Pumpkin Enabled", "Navigating to and crushing pumpkins safely.", "success")
                else
                    _G.VD_AbortPathfinding = true

                    if _G.VD_ExitSubSurfacePocket then
                        pcall(_G.VD_ExitSubSurfacePocket)
                    end

                    if _G.VD_CurrentFarmState and tostring(_G.VD_CurrentFarmState):find("PUMPKIN") then
                        _G.VD_CurrentFarmState = "IDLE"
                    end

                    pcall(function()
                        if not lastIsMobile and VirtualInputManager then
                            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.LeftShift, false, game)
                        end
                    end)

                    local character = localPlayer.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

                    if humanoid then
                        pcall(function()
                            humanoid:Move(Vector3.zero, false)
                            humanoid.WalkSpeed = 16
                        end)
                    end

                    showNotification("Auto Pumpkin Disabled", "Stopped pumpkin crushing automation.", "info")
                end

                pcall(saveSettings)
            end, UI.Accent, "AutoPumpkin")

            _G.VD_SetAutoPumpkinToggle = collapsibleToggle2.setValue
            controlRegistry.AutoPumpkin = collapsibleToggle2

            local toggle7 = createToggle(collapsibleToggle2.content, "Flee Killer When Close", settings2.AutoPumpkinFleeKiller, function(autoPumpkinFleeKiller)
                settings2.AutoPumpkinFleeKiller = autoPumpkinFleeKiller

                if not autoPumpkinFleeKiller then
                    if _G.VD_ExitSubSurfacePocket then
                        pcall(_G.VD_ExitSubSurfacePocket)
                    end
                end

                pcall(saveSettings)
            end, UI.Accent, "AutoPumpkinFleeKiller")

            controlRegistry.AutoPumpkinFleeKiller = toggle7
            createSection(tabFarm, "Generator Automations", UI.Accent)

            local collapsibleToggle3 = createCollapsibleToggle(tabFarm, "Auto Skill Check", settings2.AutoSkillCheck, function(autoSkillCheck)
                settings2.AutoSkillCheck = autoSkillCheck
                pcall(saveSettings)
            end, UI.Accent, "AutoSkillCheck")

            controlRegistry.AutoSkillCheck = {setValue = collapsibleToggle3.setValue}

            controlRegistry.InstantSkillCheck = createToggle(collapsibleToggle3.content, "Instant Skill Check", settings2.InstantSkillCheck, function(instantSkillCheck)
                settings2.InstantSkillCheck = instantSkillCheck
                pcall(saveSettings)
            end, UI.Accent, "InstantSkillCheck")

            controlRegistry.SkillCheckMode = createSelector(collapsibleToggle3.content, "Skill Check Mode", {"Perfect", "Normal", "Hybrid"}, {"Perfect", "Normal", "Hybrid"}, settings2.SkillCheckMode or "Perfect", function(skillCheckMode)
                settings2.SkillCheckMode = skillCheckMode
                pcall(saveSettings)
            end)

            controlRegistry.PerfectHitRate = createSlider(collapsibleToggle3.content, "Perfect Hit Rate (%)", 0, 100, settings2.PerfectHitRate or 100, function(perfectHitRate)
                settings2.PerfectHitRate = perfectHitRate
                pcall(saveSettings)
            end, UI.Accent)

            controlRegistry.KingsScourgePerfectRate = createSlider(collapsibleToggle3.content, "King's Scourge Perfect Rate (%)", 0, 100, settings2.KingsScourgePerfectRate or 30, function(kingsScourgePerfectRate)
                settings2.KingsScourgePerfectRate = kingsScourgePerfectRate
                pcall(saveSettings)
            end, UI.AccentCyan)

            controlRegistry.SkillCheckSpeedVal = createSliderFloat(collapsibleToggle3.content, "Skill Check Speed", 0.1, 3, settings2.SkillCheckSpeedVal or 1, function(skillCheckSpeedVal)
                settings2.SkillCheckSpeedVal = skillCheckSpeedVal
                pcall(saveSettings)
            end, UI.Accent)

            controlRegistry.NoSkillChecks = createToggle(collapsibleToggle3.content, "No Skill Checks (Remove Checks)", settings2.NoSkillChecks, function(noSkillChecks)
                if noSkillChecks and not isPremiumActive("NoSkillChecks") then
                    showNotification(
                        "Premium Feature +",
                        "Unlock the Premium version to use this feature!",
                        "warning"
                    )

                    if controlRegistry.NoSkillChecks and controlRegistry.NoSkillChecks.setValue then
                        controlRegistry.NoSkillChecks.setValue(false)
                    end

                    return
                end

                settings2.NoSkillChecks = noSkillChecks
                pcall(saveSettings)
                local character = localPlayer.Character

                if character then
                    if noSkillChecks then
                        if _G.VD_StashSkillchecks then
                            pcall(_G.VD_StashSkillchecks)
                        end
                    else
                        if _G.VD_RestoreSkillchecks then
                            pcall(_G.VD_RestoreSkillchecks)
                        end
                    end
                end
            end, UI.Accent, "NoSkillChecks")

            createSection(tabFarm, "Killer Automations", UI.Accent)

            local toggle8 = createToggle(tabFarm, "Killer Auto Farm", settings2.AutoFarmKiller, function(autoFarmKiller)
                if autoFarmKiller then
                    if settings2.AutoFarmAFKTotal then
                        settings2.AutoFarmAFKTotal = false

                        if _G.VD_SetTotalAFKToggle then
                            _G.VD_SetTotalAFKToggle(false)
                        end
                    end

                    if settings2.InstantFinishlineEscape then
                        settings2.InstantFinishlineEscape = false

                        if _G.VD_SetInstantEscapeToggle then
                            _G.VD_SetInstantEscapeToggle(false)
                        end
                    end
                end

                settings2.AutoFarmKiller = autoFarmKiller

                if autoFarmKiller then
                    _G.VD_FarmState.farmTeamStartTime = tick()
                    _G.VD_FarmState.farmLastTeamName = ""
                    showNotification("Killer Auto Farm Enabled", "Starting automatic survivor hunting.", "success")
                end

                pcall(saveSettings)
            end, UI.Accent, "KillerAutoFarm")

            _G.VD_SetKillerFarmToggle = toggle8.setValue
            _G.VD_SetKillerFarmToggle = _G.VD_SetKillerFarmToggle
            controlRegistry.AutoFarmKiller = toggle8

            local toggle9 = createToggle(tabFarm, "Anti Wiggle (Auto-Drop Survivor)", settings2.AntiWiggle, function(antiWiggle)
                if not isPremiumActive() then
                    showNotification(
                        "Premium Feature +",
                        "Unlock the Premium version to use this feature!",
                        "warning"
                    )

                    return
                end

                settings2.AntiWiggle = antiWiggle

                if antiWiggle and isPremiumActive() then
                    showNotification(
                        "Anti Wiggle Enabled",
                        "Will auto-drop survivors right before wiggle escapes.",
                        "success"
                    )
                end

                pcall(saveSettings)
            end, UI.Accent, "AntiWiggle")

            _G.VD_SetAntiWiggleToggle = toggle9.setValue
            controlRegistry.AntiWiggle = toggle9
            createSection(tabFarm, "Telemetry & State", UI.Accent)
            local frame4 = Instance.new("Frame")
            frame4.Size = UDim2.new(1, 0, 0, 32)
            frame4.BackgroundColor3 = UI.Card
            frame4.BackgroundTransparency = 0.5
            frame4.Parent = tabFarm
            Instance.new("UICorner", frame4).CornerRadius = UDim.new(0, UI.CardRadius)
            local uiStroke = Instance.new("UIStroke", frame4)
            uiStroke.Color = UI.StrokeDim
            uiStroke.Thickness = 0.8
            _G.VD_FarmStatusLabel = Instance.new("TextLabel")
            _G.VD_FarmStatusLabel.Size = UDim2.new(1, -20, 1, 0)
            _G.VD_FarmStatusLabel.Position = UDim2.new(0, 10, 0, 0)
            _G.VD_FarmStatusLabel.BackgroundTransparency = 1
            _G.VD_FarmStatusLabel.Text = "Status: Idle"
            _G.VD_FarmStatusLabel.TextColor3 = UI.TextSub
