    local function fnContent2()
        do
            createSection(tabSelf, "Speed Customizations", UI.Accent)

            controlRegistry.ModifierTeamFilter = createSelector(tabSelf, "Modifiers Active For", {"Both Teams", "Survivors Only", "Killer Only"}, {"Both", "Survivors", "Killer"}, settings2.ModifierTeamFilter or "Both", function(modifierTeamFilter)
                settings2.ModifierTeamFilter = modifierTeamFilter
                pcall(applyLocalPlayerModifiers)
                pcall(saveSettings)
            end)

            controlRegistry.VaultSpeed = createSlider(tabSelf, "Vault Speed Factor", 1, 2.3, math.clamp(settings2.VaultSpeed or 1, 1, 2.3), function(vaultSpeed)
                settings2.VaultSpeed = vaultSpeed
                pcall(applyLocalPlayerModifiers)
                pcall(saveSettings)
            end, UI.AccentCyan, 0.01, "x")

            local collapsibleToggle = createCollapsibleToggle(tabSelf, "Speed Boost Enabled", settings2.SpeedBoostEnabled, function(speedBoostEnabled)
                if speedBoostEnabled then
                    local team = localPlayer.Team
                    local name = team and team.Name
                    local modifierTeamFilter = settings2.ModifierTeamFilter or "Both"
                    local flag12 = false

                    if modifierTeamFilter == "Both" then
                        flag12 = name == "Survivors" or name == "Killer"
                    elseif modifierTeamFilter == "Survivors" then
                        flag12 = name == "Survivors"
                    elseif modifierTeamFilter == "Killer" then
                        flag12 = name == "Killer"
                    end

                    if not flag12 then
                        settings2.SpeedBoostEnabled = false
                        pcall(saveSettings)

                        if fn1 then
                            pcall(fn1)
                        end

                        showNotification("Speed Boost", "Speed Boost team filter active!", "warning")
                        return
                    end
                end

                settings2.SpeedBoostEnabled = speedBoostEnabled
                pcall(applyLocalPlayerModifiers)
                pcall(saveSettings)
            end, nil, "ToggleSpeedBoost")

            controlRegistry.SpeedBoostEnabled = {setValue = collapsibleToggle.setValue}

            controlRegistry.SpeedBoost = createSliderFloat(collapsibleToggle.content, "Speed Boost Multiplier", 1, 6, settings2.SpeedBoost, function(speedBoost)
                settings2.SpeedBoost = speedBoost
                pcall(applyLocalPlayerModifiers)
                pcall(saveSettings)
            end)

            controlRegistry.CountSpeedPerks = createToggle(collapsibleToggle.content, "Count Speed Perks / Slow Downs", settings2.CountSpeedPerks, function(countSpeedPerks)
                settings2.CountSpeedPerks = countSpeedPerks
                pcall(applyLocalPlayerModifiers)
