            local function fnSpectator()
                local list10 = {}

                pcall(function()
                    local spectator = localPlayer.PlayerGui:FindFirstChild("Spectator")
                    local inventory = spectator and spectator:FindFirstChild("Inventory", true)
                    local browseItems = inventory and inventory:FindFirstChild("Browse_items", true)
                    local loadout = browseItems and browseItems:FindFirstChild("loadout", true)
                    local perks = loadout and loadout:FindFirstChild("Perks", true)

                    if perks then
                        for _, child in ipairs(perks:GetChildren()) do
                            if child:IsA("GuiObject")
                                and child.Name ~= "UIListLayout"
                                and child.Name ~= "UIGridLayout" then
                                table.insert(list10, child.Name)
                            end
                        end
                    end
                end)

                if #list10 == 0 then
                    list10 = {
                        "Group Project",
                        "No Pain No Gain",
                        "On Screen Fear",
                        "Flowstate",
                        "Adrenaline",
                        "Sprint Burst",
