                return list10
            end

            local function fnWait(perkLoadout)
                if not perkLoadout then return end
                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                remotes = remotes and remotes:FindFirstChild("Shop")
                remotes = remotes and remotes:FindFirstChild("UnequipPerk")
                local remotes2 = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                remotes2 = remotes2 and remotes2:FindFirstChild("Shop")
                remotes2 = remotes2 and remotes2:FindFirstChild("EquipPerk")

                if not remotes or not remotes2 then
                    showNotification("Perk Loadouts", "Shop remotes not found! Make sure you are in game.", "error")
                    return
                end

                pcall(function()
                    remotes:FireServer(3)
                    task.wait(0.05)
                    remotes:FireServer(2)
                    task.wait(0.05)
                    remotes:FireServer(1)
                    task.wait(0.05)

                    if perkLoadout.Perk3 and perkLoadout.Perk3 ~= "None" and perkLoadout.Perk3 ~= "" then
                        remotes2:FireServer(perkLoadout.Perk3, 3)
                        task.wait(0.05)
                    end

                    if perkLoadout.Perk2 and perkLoadout.Perk2 ~= "None" and perkLoadout.Perk2 ~= "" then
                        remotes2:FireServer(perkLoadout.Perk2, 2)
                        task.wait(0.05)
                    end

                    if perkLoadout.Perk1 and perkLoadout.Perk1 ~= "None" and perkLoadout.Perk1 ~= "" then
                        remotes2:FireServer(perkLoadout.Perk1, 1)
                        task.wait(0.05)
                    end

                    showNotification("Perk Loadouts", "Loadout applied successfully!", "success")
                end)
            end

