            local flag12 = false
            local cFrame = nil

            local function doAutoUnhook()
                local character = localPlayer.Character

                local humanoidRootPart2 = character
                    and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso"))

                local humanoid = character and character:FindFirstChildOfClass("Humanoid")

                if not humanoidRootPart2 or not humanoid or humanoid.Health <= 0 then
                    showNotification("Auto Unhook", "Character not found or dead!", "error")
                    return
                end

                if flag12 then
                    flag12 = false

                    if cFrame and humanoidRootPart2 and humanoidRootPart2.Parent then
                        humanoidRootPart2.CFrame = cFrame
                        humanoidRootPart2.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    end

                    showNotification("Auto Unhook", "Auto Unhook cancelled! Returned to hook.", "warning")
                    return
                end

                cFrame = humanoidRootPart2.CFrame
                flag12 = true
                showNotification("Auto Unhook", "Starting Auto Unhook sequence...", "info")

                task.spawn(function()
                    local success2, result2 = pcall(function()
                        local instance2 = nil
                        local list12 = {}

                        for _, descendant in ipairs(workspace:GetDescendants()) do
                            if descendant:IsA("Model")
                                and (descendant.Name == "Generator" or descendant.Name:find("Generator")) then
                                table.insert(list12, descendant)
                            end
                        end

                        for _, list12Item in ipairs(list12) do
                            local mainPart = list12Item:FindFirstChild("MainPart")
                                or list12Item:FindFirstChild("Engine")
                                or list12Item:FindFirstChildWhichIsA("BasePart")

                            if mainPart then
                                instance2 = list12Item
                                break
                            end
                        end

                        local replicatedStorage = game:GetService("ReplicatedStorage")
                        local remotes = replicatedStorage:FindFirstChild("Remotes")
                        local generator = remotes and remotes:FindFirstChild("Generator")

                        local repairEvent = generator and generator:FindFirstChild("RepairEvent")
                            or replicatedStorage:FindFirstChild("RepairEvent", true)

                        if instance2 then
                            local mainPart = instance2:FindFirstChild("MainPart")
                                or instance2:FindFirstChild("Engine")
                                or instance2:FindFirstChildWhichIsA("BasePart")

                            if mainPart then
                                humanoidRootPart2.CFrame = mainPart.CFrame + Vector3.new(0, 2, 0)
                                humanoidRootPart2.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                                task.wait(0.2)
                            end

                            local v6 = nil

                            for _, child in ipairs(instance2:GetChildren()) do
                                if child.Name:lower():find("point") then
                                    v6 = child
                                    break
                                end
                            end

                            if repairEvent and v6 then
                                local httpService2 = game:GetService("HttpService")
                                local guid = "FEB67C57-1E59-4609-B765-6304242AC088"

                                pcall(function()
                                    guid = httpService2:GenerateGUID(false)
                                end)

                                local character2 = localPlayer.Character

                                pcall(function()
                                    repairEvent:FireServer(v6, true, nil, guid, character2)
                                end)

                                task.wait(0.25)

                                pcall(function()
                                    repairEvent:FireServer(v6, false, nil, guid, character2)
                                end)

                                task.wait(0.2)
                            end
                        end

                        local function fnAnticampCharge()
                            local character2 = localPlayer.Character
                            local anticampCharge = nil

                            if character2 then
                                anticampCharge = character2:GetAttribute("anticampCharge")
                                    or character2:GetAttribute("AntiCampCharge")
                                    or character2:GetAttribute("AnticampCharge")
                                    or character2:GetAttribute("antiCampCharge")
                            end

                            if anticampCharge == nil then
                                anticampCharge = localPlayer:GetAttribute("anticampCharge")
                                    or localPlayer:GetAttribute("AntiCampCharge")
                                    or localPlayer:GetAttribute("AnticampCharge")
                                    or localPlayer:GetAttribute("antiCampCharge")
                            end

                            if anticampCharge == nil and character2 then
                                local anticampCharge2 = character2:FindFirstChild("anticampCharge", true)
                                    or character2:FindFirstChild("AntiCampCharge", true)

                                if anticampCharge2 and anticampCharge2:IsA("ValueObject") then
                                    anticampCharge = anticampCharge2.Value
                                end
                            end

                            return tonumber(anticampCharge) or 0
                        end

                        local now = tick()
                        local num4 = 60
                        local v6 = -1

                        while flag12 and tick() - now < num4 do
                            local value = fnAnticampCharge()
                            if value >= 100 then break end
                            local num5 = math.floor(value)

                            if num5 % 25 == 0 and num5 ~= v6 and num5 > 0 then
                                v6 = num5

                                showNotification(
                                    "Auto Unhook",
                                    string.format("Charging Anti-Camp: %d%%", num5),
                                    "info"
                                )
                            end

                            local instance3 = nil

                            if callback3 then
                                local list13 = callback3()

                                if list13 and #list13 > 0 then
                                    for _, list13Item in ipairs(list13) do
                                        local humanoidRootPart3 = list13Item and (list13Item:FindFirstChild("HumanoidRootPart")
                                            or list13Item:FindFirstChild("Torso"))

                                        if humanoidRootPart3 then
                                            instance3 = humanoidRootPart3
                                            break
                                        end
                                    end
                                end
                            end

                            if not instance3 then
                                for _, player in ipairs(Players:GetPlayers()) do
                                    if player ~= localPlayer and player.Character then
                                        local character2 = player.Character

                                        local flag13 = player:GetAttribute("Role") == "Killer"
                                            or player:GetAttribute("IsKiller") == true
                                            or character2:GetAttribute("Role") == "Killer"
                                            or character2:GetAttribute("IsKiller") == true

                                        if not flag13 and player.Team then
                                            local str = player.Team.Name:lower()

                                            if str:find("killer") or str:find("slasher") or str:find("monster") then
                                                flag13 = true
                                            end
                                        end

                                        if flag13 then
                                            instance3 = character2:FindFirstChild("HumanoidRootPart")
                                                or character2:FindFirstChild("UpperTorso")
                                                or character2:FindFirstChild("Torso")

                                            if instance3 then break end
                                        end
                                    end
                                end
                            end

                            if instance3 and humanoidRootPart2 and humanoidRootPart2.Parent then
                                humanoidRootPart2.CFrame = CFrame.new(instance3.Position - Vector3.new(0, 16, 0))
                                humanoidRootPart2.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            end

                            task.wait(0.06)
                        end

                        if humanoidRootPart2 and humanoidRootPart2.Parent and cFrame then
                            humanoidRootPart2.CFrame = cFrame
                            humanoidRootPart2.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            task.wait(0.2)
                        end

                        local selfUnHookEvent = nil

                        pcall(function()
                            local carry = remotes and remotes:FindFirstChild("Carry")
                            selfUnHookEvent = carry and carry:FindFirstChild("SelfUnHookEvent")

                            if not selfUnHookEvent then
                                selfUnHookEvent = replicatedStorage:FindFirstChild("SelfUnHookEvent", true)
                            end
                        end)

                        if selfUnHookEvent then
                            selfUnHookEvent:FireServer()
                            showNotification("Auto Unhook", "Self-Unhook event executed successfully!", "success")
                        else
                            showNotification("Auto Unhook", "SelfUnHookEvent not found in Remotes!", "error")
                        end
                    end)

                    flag12 = false

                    if not success2 then
                        showNotification("Auto Unhook", "Error: " .. tostring(result2), "error")
                    end
                end)
            end

