            local function fnCurrentCamera()
                local camera2 = workspace.CurrentCamera
                if not camera2 then return nil end
                local raycastParams = RaycastParams.new()
                raycastParams.FilterType = Enum.RaycastFilterType.Include
                local filterDescendantsInstances = {}

                for _, instance2 in ipairs(cachedPallets) do
                    if instance2 and instance2.Parent then
                        table.insert(filterDescendantsInstances, instance2)
                    end
                end

                raycastParams.FilterDescendantsInstances = filterDescendantsInstances
                local position = camera2.CFrame.Position
                local num4 = camera2.CFrame.LookVector * 500
                local raycastResult = workspace:Raycast(position, num4, raycastParams)

                if raycastResult and raycastResult.Instance then
                    local instance2 = raycastResult.Instance
                    local instance2_2 = instance2

                    while instance2_2 and instance2_2 ~= workspace do
                        if table.find(cachedPallets, instance2_2) then return instance2_2 end
                        instance2_2 = instance2_2.Parent
                    end
                end

                return nil
            end

            local function fnAdornee()
                if not settings2.RemoteDropPallet then
                    if instance then
                        pcall(function()
                            instance:Destroy()
                        end)

                        instance = nil
                    end

                    return
                end

                local adornee = fnCurrentCamera()

                if adornee then
                    local remoteDropPalletColor = settings2.RemoteDropPalletColor or Color3.fromRGB(0, 255, 255)

                    if not instance or instance.Parent == nil then
                        pcall(function()
                            if instance then
                                instance:Destroy()
                            end
                        end)

                        instance = Instance.new("Highlight")
                        instance.Name = "VD_PalletTargetHighlight"
                        instance.FillColor = remoteDropPalletColor
                        instance.FillTransparency = 0.6
                        instance.OutlineColor = remoteDropPalletColor
                        instance.OutlineTransparency = 0
                    else
                        instance.FillColor = remoteDropPalletColor
                        instance.OutlineColor = remoteDropPalletColor
                    end

                    if instance.Adornee ~= adornee then
                        instance.Adornee = adornee
                        instance.Parent = adornee
                    end
                else
                    if instance then
                        instance.Adornee = nil
                        instance.Parent = nil
                    end
                end
            end

            local function fnShowNotification3()
                if not settings2.RemoteDropPallet then return end
                local model = fnCurrentCamera()

                if not model then
                    showNotification("Remote Drop Pallet", "No pallet targeted!", "warning")
                    return
                end

                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                local pallet = remotes and remotes:FindFirstChild("Pallet")
                local palletDropEvent = pallet and pallet:FindFirstChild("PalletDropEvent")

                if not palletDropEvent then
                    showNotification("Remote Drop Pallet", "PalletDropEvent remote not found!", "error")
                    return
                end

                local character = localPlayer.Character
                local humanoidRootPart2 = character and character:FindFirstChild("HumanoidRootPart")

                if not humanoidRootPart2 then
                    showNotification("Remote Drop Pallet", "Character root not found!", "error")
                    return
                end

                local intact = model:FindFirstChild("Intact")

                if not intact then
                    showNotification("Remote Drop Pallet", "Pallet already dropped or broken!", "warning")
                    return
                end

                local children = intact:GetChildren()

                local basePart = children[8] and children[8]:IsA("BasePart") and children[8]
                    or intact:FindFirstChildWhichIsA("BasePart")
                    or children[1] and children[1]:IsA("BasePart") and children[1]
                    or model:FindFirstChildWhichIsA("BasePart")
                    or model:IsA("Model") and model.PrimaryPart

                if not basePart then
                    showNotification("Remote Drop Pallet", "No valid pallet part found!", "error")
                    return
                end

                local position = basePart.Position
                local distance = (humanoidRootPart2.Position - position).Magnitude
                local guid = game:GetService("HttpService"):GenerateGUID(false)
                local flag13 = false

                if distance <= 14 then
                    pcall(function()
                        _G.VD_LastRemoteDropTime = tick()
                        palletDropEvent:FireServer(basePart, position, Vector3.new(0, 0, 0), guid, character)
                        flag13 = true
                    end)
                else
                    local cFrame2 = humanoidRootPart2.CFrame
                    local instance2_2 = position + Vector3.new(0, 1.5, 0)
                    safeSegmentedTeleport(humanoidRootPart2, instance2_2)
                    task.wait(0.05)

                    pcall(function()
                        _G.VD_LastRemoteDropTime = tick()
                        palletDropEvent:FireServer(basePart, position, Vector3.new(0, 0, 0), guid, character)
                        flag13 = true
                    end)

                    task.wait(0.08)
                    safeSegmentedTeleport(humanoidRootPart2, cFrame2)
                end

                if flag13 then
                    showNotification("Remote Drop Pallet", "Pallet dropped remotely!", "success")
                else
                    showNotification("Remote Drop Pallet", "Failed to drop pallet (already dropped?)", "warning")
                end
            end

            task.spawn(function()
                while activeLoop do
