                    return
                end

                local character = localPlayer.Character
                local humanoidRootPart2 = character and character:FindFirstChild("HumanoidRootPart")

                if not humanoidRootPart2 then
                    showNotification("Drop Pallets", "Character root not found!", "error")
                    return
                end

                local num4 = 0
                local map11 = workspace:FindFirstChild("Map")
                local resources = map11 and map11:FindFirstChild("resources")
                local pallets = resources and resources:FindFirstChild("Pallets")
                local list12 = {}

                if pallets then
                    for _, child in ipairs(pallets:GetChildren()) do
                        table.insert(list12, child)
                    end
                end

                for _, value in ipairs(cachedPallets) do
                    if not table.find(list12, value) then
                        table.insert(list12, value)
                    end
                end

