                    if not success2 or not result2 then
                        success2, result2 = pcall(v5)
                    end

                    if success2 and type(result2) == "table" then
                        for _, result2Item in ipairs(result2) do
                            local match = tostring(result2Item):match("[^/\\]+$") or tostring(result2Item)
                            local str6 = match:lower()

                            if not str6:find("^dbd_hud_") and not str6:find("dbd_hud_") then
                                local match2 = match:match("%.([^%.]+)$")

                                if match2 then
                                    match2 = match2:lower()

                                    if match2 == "png" or match2 == "jpg" or match2 == "jpeg" or match2 == "webp" then
                                        table.insert(list11, match)
                                    end
                                end
                            end
                        end
                    end
                end

                return list11
            end

