            local function fnCheck()
                local keybinds = settings2.Keybinds or {}
                local list12 = {}
                local map12 = {}

                for k, keybind in pairs(keybinds) do
                    if keybind and keybind ~= "None" and keybind ~= "" then
                        local map11Item = map11[k]
                        local name = map11Item and map11Item.name or k
                        local short = map11Item and map11Item.short or name

                        local check = map11Item and map11Item.check or function()
                            if map5 and map5[k] then return map5[k]() == true end
                            if settings2[k] ~= nil then return settings2[k] == true end
                            return false
                        end

                        table.insert(list12, {key = k, val = keybind, name = name, short = short, check = check})
                        map12[name] = true
                    end
                end

                for _, list11Item in ipairs(list11) do
                    if list11Item.check() and not map12[list11Item.name] then
                        table.insert(list12, {
                            key = list11Item.name,
                            val = "",
                            name = list11Item.name,
                            short = list11Item.short or list11Item.name,
                            check = list11Item.check,
                        })

                        map12[list11Item.name] = true
                    end
                end

                table.sort(list12, function(arg1, arg2)
                    return arg1.name:lower() < arg2.name:lower()
                end)

                return list12
            end

