                local function fnFromRGB3(key2)
                    local now = tick()
                    local accent = UI.Accent or Color3.fromRGB(255, 255, 255)

                    if key2 == "Flowstate" then
                        if not settings2.FlowstatePerk then
                            return "OFF", Color3.fromRGB(120, 120, 130)
                        end

                        local num4 = (_G.VD_FlowstateActiveOverrideEnd or 0) - now

                        if num4 > 0 then
                            return string.format("BOOST %.1fs", num4), Color3.fromRGB(0, 230, 255)
                        end

                        local value = (_G.VD_FlowstateCooldownEnd or 0) - now

                        if value > 0 then
                            return string.format("%ds", math.ceil(value)), Color3.fromRGB(255, 85, 85)
                        end

                        return "READY", accent
                    elseif key2 == "QuickRecovery" then
                        if not settings2.SimulateQuickRecovery then
                            return "OFF", Color3.fromRGB(120, 120, 130)
                        end

                        local num4 = (_G.VD_QuickRecoveryBoostEnd or 0) - now

