            OPENINGGATE = UI.AccentGreen,
            FLEEING = UI.Danger,
            ESCAPING = UI.AccentGreen,
            ESCAPED = UI.AccentGreen,
            HUNTING = UI.Danger,
            CARRYING = UI.Warning,
            HANGING = UI.AccentCyan,
            ["PAUSED (Knocked/Hooked)"] = Color3.fromRGB(200, 200, 50),
            ["PAUSED (Spectating/Lobby)"] = UI.Muted,
            ["PAUSED (Killer Team)"] = UI.Danger,
            ["PAUSED (Survivors Team)"] = UI.Danger,
        }

        local map11Item = map11[value] or tostring(value)
        local map12Item = map12[value] or UI.Muted

        if tostring(value):find("WAITING") then
            map12Item = UI.AccentCyan
        elseif tostring(value):find("PUMPKIN") then
            map12Item = UI.Accent
        end

        if _G.VD_HomeStatusLabel then
            _G.VD_HomeStatusLabel.Text = map11Item
            _G.VD_HomeStatusLabel.TextColor3 = map12Item
        end

        if _G.VD_HomeStatusDot then
            _G.VD_HomeStatusDot.BackgroundColor3 = map12Item
        end

        if _G.VD_FarmStatusLabel then
            _G.VD_FarmStatusLabel.Text = "Status: " .. map11Item
            _G.VD_FarmStatusLabel.TextColor3 = map12Item
        end
