    task.spawn(function()
        local h = 0
        local num4 = 0
        local enabled = false

        while activeLoop do
            task.wait(0.05)
            num4 = num4 + 1

            if num4 >= 2 then
                num4 = 0
                enabled = not enabled
            end

            pcall(function()
                if num4 % 4 == 0 then
                    local killerStainColor = settings2.KillerStainColor or Color3.fromRGB(255, 0, 0)

                    for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
                        local character = player.Character
                        local head = character and character:FindFirstChild("Head")
                        local redSurfaceLight = head and head:FindFirstChild("RedSurfaceLight")

                        if redSurfaceLight and redSurfaceLight:IsA("Light") then
                            if redSurfaceLight.Color ~= killerStainColor then
                                redSurfaceLight.Color = killerStainColor
                            end
                        end
                    end
                end

                local character = localPlayer.Character
                local flashlight = character and character:FindFirstChild("Flashlight")

                if flashlight then
                    local spotLight = flashlight:FindFirstChildOfClass("SpotLight")
                        or flashlight:FindFirstChild("SpotLight", true)

                    if spotLight then
                        if spotLight ~= _G.VD_LastHookedLight then
                            if _G.VD_LightChangedConn then
                                pcall(function()
                                    _G.VD_LightChangedConn:Disconnect()
                                end)
                            end

                            _G.VD_LastHookedLight = spotLight
                            _G.VD_FlashlightOnState = spotLight.Enabled

                            _G.VD_LightChangedConn = spotLight:GetPropertyChangedSignal("Enabled"):Connect(function()
                                if _G.VD_IsChangingEnabled then return end
                                _G.VD_FlashlightOnState = spotLight.Enabled
                            end)

                            registerConnection(_G.VD_LightChangedConn)
                        end

                        local flashlightColor = settings2.FlashlightColor or Color3.fromRGB(255, 255, 255)

                        if settings2.FlashlightEffect == "Rainbow" then
                            h = (h + 0.008) % 1
                            flashlightColor = Color3.fromHSV(h, 1, 1)
                        end

                        for _, descendant in ipairs(flashlight:GetDescendants()) do
                            if descendant:IsA("Light") then
                                descendant.Color = flashlightColor

                                if _G.VD_FlashlightOnState then
                                    if settings2.FlashlightEffect == "Ultra Bright" then
                                        _G.VD_IsChangingEnabled = true
                                        descendant.Enabled = true
                                        _G.VD_IsChangingEnabled = false
                                        descendant.Range = 250
                                        descendant.Brightness = 15
                                    elseif settings2.FlashlightEffect == "Strobe" then
                                        _G.VD_IsChangingEnabled = true
                                        descendant.Enabled = enabled
                                        _G.VD_IsChangingEnabled = false
                                    else
                                        if _G.VD_LastFlashlightEffect == "Ultra Bright" then
                                            descendant.Range = 51
                                            descendant.Brightness = 1
                                        end
                                    end
                                else
                                    _G.VD_IsChangingEnabled = true
                                    descendant.Enabled = false
                                    _G.VD_IsChangingEnabled = false

                                    if _G.VD_LastFlashlightEffect == "Ultra Bright" then
                                        descendant.Range = 51
                                        descendant.Brightness = 1
                                    end
                                end
                            elseif descendant:IsA("Beam") then
                                descendant.Color = ColorSequence.new(flashlightColor)

                                if _G.VD_FlashlightOnState then
                                    if settings2.FlashlightEffect == "Strobe" then
                                        descendant.Enabled = enabled
                                    elseif settings2.FlashlightEffect == "Ultra Bright" then
                                        descendant.Enabled = true
                                    end
                                else
                                    descendant.Enabled = false
                                end
                            elseif descendant:IsA("BasePart") then
                                local str = descendant.Name:lower()

                                if str:find("beam")
                                    or str:find("light")
                                    or str:find("cone")
                                    or descendant.Transparency > 0 and descendant.Transparency < 1 then
                                    descendant.Color = flashlightColor

                                    if _G.VD_FlashlightOnState then
                                        if settings2.FlashlightEffect == "Strobe" then
                                            descendant.Transparency = enabled and 0.5 or 1
                                        elseif settings2.FlashlightEffect == "Ultra Bright" then
                                            descendant.Transparency = 0.4
                                        end
                                    else
                                        descendant.Transparency = 1
                                    end
                                end
                            end
                        end
                    end

                    _G.VD_LastFlashlightEffect = settings2.FlashlightEffect
                end
            end)
        end
    end)

