    function teleportToInstance(part)
        if not localPlayer
            or not localPlayer.Character
            or not localPlayer.Character:FindFirstChild("HumanoidRootPart") then
            return
        end

        local primaryPart

        if part:IsA("Model") then
            primaryPart = part.PrimaryPart or part:FindFirstChildWhichIsA("BasePart")
        elseif part:IsA("BasePart") then
            primaryPart = part
        end

        if primaryPart then
            if _G.VD_StopAllInteractions then
                pcall(_G.VD_StopAllInteractions)
                task.wait(0.15)
            end

            local humanoidRootPart2 = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

            if humanoidRootPart2 then
                local num4 = primaryPart.Position + Vector3.new(0, 1.5, 0)

                if settings2.PathfindingTP ~= false and _G.VD_SmartWalkTo then
                    _G.VD_AbortPathfinding = true
                    task.wait(0.03)
                    _G.VD_AbortPathfinding = false

                    task.spawn(function()
                        local v5 = _G.VD_SmartWalkTo(num4, 3.5)

                        if not v5
                            and (primaryPart.Position - humanoidRootPart2.Position).Magnitude > 4
                            and not _G.VD_AbortPathfinding then
                            safeSegmentedTeleport(humanoidRootPart2, primaryPart.CFrame + Vector3.new(0, 3, 0))
                        end
                    end)

                    showNotification("Teleport", "Pathfinding to map object...", "info")
                else
