    function collectTPEntries()
        local list11 = {}
        local map12 = {}

        local function fnInsert(instance2, label)
            if instance2 and instance2.Parent and not map12[instance2] then
                map12[instance2] = true
                table.insert(list11, {instance = instance2, label = label})
            end
        end

        local str5 = activeTPFilter or "All"

        if str5 == "All" or str5 == "Generator" then
            for _, instance2_2 in ipairs(cachedGenerators or {}) do
                if not isGeneratorCompleted(instance2_2) then
                    fnInsert(instance2_2, "Generator")
                end
            end

            if #list11 == 0 and (str5 == "Generator" or str5 == "All") then
                local map13 = workspace:FindFirstChild("Map")
                local gens = map13 and map13:FindFirstChild("Gens")

                if gens then
                    for _, child in ipairs(gens:GetChildren()) do
                        if (child.Name == "Generator" or string.find(child.Name:lower(), "generator"))
                            and not isGeneratorCompleted(child) then
                            fnInsert(child, "Generator")
                        end
                    end
                end

                for _, descendant in ipairs(workspace:GetDescendants()) do
                    if (descendant.Name == "Generator" or descendant.Name:lower():find("generator"))
                        and descendant:IsA("Model")
                        and not isGeneratorCompleted(descendant) then
                        fnInsert(descendant, "Generator")
                    end
                end
            end
        end

        if str5 == "All" or str5 == "Hook" then
            for _, instance2_2 in ipairs(cachedHooks or {}) do
                fnInsert(instance2_2, "Hook")
            end

            if #list11 == 0 and (str5 == "Hook" or str5 == "All") then
                for _, descendant in ipairs(workspace:GetDescendants()) do
                    if descendant.Name == "Hook"
                        or descendant.Name == "HookPoint"
                        or descendant.Name:lower():find("hook") then
                        local descendant2 = descendant:IsA("BasePart") and descendant
                            or descendant:FindFirstChild("HookPoint")
                            or descendant:IsA("Model") and descendant.PrimaryPart
                            or descendant:FindFirstChildWhichIsA("BasePart")

                        if descendant2 then
                            fnInsert(descendant2, "Hook")
                        end
                    end
                end
            end
        end

        if str5 == "All" or str5 == "Pallet" then
            for _, instance2_2 in ipairs(cachedPallets or {}) do
                fnInsert(instance2_2, "Pallet")
            end

            if #list11 == 0 and (str5 == "Pallet" or str5 == "All") then
                for _, descendant in ipairs(workspace:GetDescendants()) do
                    if descendant.Name == "Pallet" or descendant.Name:lower():find("pallet") then
                        fnInsert(descendant, "Pallet")
                    end
                end
            end
        end

        if str5 == "All" or str5 == "Vault" then
            for _, instance2_2 in ipairs(cachedVaults or {}) do
                fnInsert(instance2_2, "Vault")
            end

            if #list11 == 0 and (str5 == "Vault" or str5 == "All") then
                for _, descendant in ipairs(workspace:GetDescendants()) do
                    if descendant.Name == "Vault"
                        or descendant.Name:lower():find("vault")
                        or descendant.Name == "Window"
                        or descendant.Name:lower():find("window") then
                        fnInsert(descendant, "Vault")
                    end
                end
            end
        end

        if str5 == "All" or str5 == "Gate" then
            for _, instance2_2 in ipairs(cachedGates or {}) do
                fnInsert(instance2_2, "Gate")
            end

            if #list11 == 0 and (str5 == "Gate" or str5 == "All") then
                for _, descendant in ipairs(workspace:GetDescendants()) do
                    if descendant.Name == "Gate"
                        or descendant.Name:lower():find("gate")
                        or descendant.Name:lower():find("door") then
                        fnInsert(descendant, "Gate")
                    end
                end
            end
        end

        if str5 == "All" or str5 == "Pumpkin" then
            for _, instance2_2 in ipairs(cachedPumpkins or {}) do
                fnInsert(instance2_2, "Pumpkin")
            end

            if #list11 == 0 and (str5 == "Pumpkin" or str5 == "All") then
                local map13 = workspace:FindFirstChild("Map")
                local pumpkins = map13 and map13:FindFirstChild("Pumpkins")

                if pumpkins then
                    for _, child in ipairs(pumpkins:GetChildren()) do
                        fnInsert(child, "Pumpkin")
                    end
                end
            end
        end

        for _, list11Item in ipairs(list11) do
            list11Item.dist = getDistance(list11Item.instance)
        end

        table.sort(list11, function(arg1, arg2)
            return arg1.dist < arg2.dist
        end)

        return list11
    end

    refreshTPMenu = function()
        if not tpScroll then return end
        local list11 = collectTPEntries()
        clearTPRows()

        if #list11 == 0 then
            if tpEmptyLabel then
                tpEmptyLabel.Visible = true
            end

            return
        end

        if tpEmptyLabel then
            tpEmptyLabel.Visible = false
        end

        for _, list11Item in ipairs(list11) do
            createTPRow(list11Item)
        end
    end

    function updateTPMenuDistances()
        for k, list10Item in pairs(list10) do
            if not k.Parent then
                if list10Item.row then
                    list10Item.row:Destroy()
                end

                list10[k] = nil
            else
                local distance = getDistance(k)
                local str = string.format("%s  [%dm]", list10Item.typeLabel, distance)

                if list10Item.label.Text ~= str then
                    list10Item.label.Text = str
                end
            end
        end
    end

    function makeDraggable(instance2, arg2)
        local flag12, v5, position, position2

        local function fnScale(instance3)
            local point = instance3.Position - position

            instance2.Position = UDim2.new(
                position2.X.Scale,
                position2.X.Offset + point.X,
                position2.Y.Scale,
                position2.Y.Offset + point.Y
            )
        end

        arg2.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                flag12 = true
                position = input.Position
                position2 = instance2.Position

                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        flag12 = false
                    end
                end)
            end
        end)

        arg2.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                v5 = input
            end
        end)

        registerConnection(UserInputService.InputChanged:Connect(function(input)
            if input == v5 and flag12 then
                fnScale(input)
            end
        end))
    end

    makeDraggable(mainFrame, titleBar)

    function makeResizable(instance2, textButton2_2)
        local flag12 = false
        local position = nil
        local size = nil
        local v5 = nil

        textButton2_2.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                flag12 = true
                position = input.Position
                size = instance2.Size

                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        flag12 = false
                    end
                end)
            end
        end)

        textButton2_2.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                v5 = input
            end
        end)

        registerConnection(UserInputService.InputChanged:Connect(function(input)
            if input == v5 and flag12 then
                local point = input.Position - position
                local num4 = math.clamp(size.X.Offset + point.X, 420, 1000)
                local num5 = math.clamp(size.Y.Offset + point.Y, 260, 800)
                instance2.Size = UDim2.new(0, num4, 0, num5)
                UI.MainW = num4
                UI.MainH = num5
            end
        end))
    end

