    local function sortCandidatesByPriority(list11, priority, radius)
        if not list11 or #list11 == 0 then return nil end
        radius = math.max(radius or 150, 1)

        if priority == "Furthest" then
            table.sort(list11, function(arg1, arg2_1)
                if math.abs(arg1.dist - arg2_1.dist) > 0.01 then return arg1.dist > arg2_1.dist end
                return arg1.health < arg2_1.health
            end)
        elseif priority == "Injured" then
            table.sort(list11, function(arg1, arg2_1)
                if math.abs(arg1.health - arg2_1.health) > 0.01 then return arg1.health < arg2_1.health end
                return arg1.dist < arg2_1.dist
            end)
        elseif priority == "Healed" then
            table.sort(list11, function(arg1, arg2_1)
                if math.abs(arg1.health - arg2_1.health) > 0.01 then return arg1.health > arg2_1.health end
                return arg1.dist < arg2_1.dist
            end)
        elseif priority == "NearestInjured" then
            table.sort(list11, function(arg1, arg2_1)
                local num8 = arg1.dist / radius
                local num9 = arg2_1.dist / radius
                local num10 = math.max(arg1.maxHealth or 100, 1)
                local num11 = math.max(arg2_1.maxHealth or 100, 1)
                local num12 = math.clamp(arg1.health / num10, 0, 1)
                local num13 = math.clamp(arg2_1.health / num11, 0, 1)
                local num14 = 0.5 * num8 + 0.5 * num12
                local num15 = 0.5 * num9 + 0.5 * num13
                if math.abs(num14 - num15) > 0.001 then return num14 < num15 end
                return arg1.dist < arg2_1.dist
            end)
        elseif priority == "NearestHealed" then
            table.sort(list11, function(arg1, arg2_1)
                local num8 = arg1.dist / radius
                local num9 = arg2_1.dist / radius
                local num10 = math.max(arg1.maxHealth or 100, 1)
                local num11 = math.max(arg2_1.maxHealth or 100, 1)
                local num12 = math.clamp(arg1.health / num10, 0, 1)
                local num13 = math.clamp(arg2_1.health / num11, 0, 1)
                local num14 = 0.5 * num8 + 0.5 * (1 - num12)
                local num15 = 0.5 * num9 + 0.5 * (1 - num13)
                if math.abs(num14 - num15) > 0.001 then return num14 < num15 end
                return arg1.dist < arg2_1.dist
            end)
        elseif priority == "FurthestInjured" then
            table.sort(list11, function(arg1, arg2_1)
                local num8 = arg1.dist / radius
                local num9 = arg2_1.dist / radius
                local num10 = math.max(arg1.maxHealth or 100, 1)
                local num11 = math.max(arg2_1.maxHealth or 100, 1)
                local num12 = math.clamp(arg1.health / num10, 0, 1)
                local num13 = math.clamp(arg2_1.health / num11, 0, 1)
                local num14 = 0.5 * (1 - num8) + 0.5 * num12
                local num15 = 0.5 * (1 - num9) + 0.5 * num13
                if math.abs(num14 - num15) > 0.001 then return num14 < num15 end
                return arg1.dist > arg2_1.dist
            end)
        elseif priority == "FurthestHealed" then
            table.sort(list11, function(arg1, arg2_1)
                local num8 = arg1.dist / radius
                local num9 = arg2_1.dist / radius
                local num10 = math.max(arg1.maxHealth or 100, 1)
                local num11 = math.max(arg2_1.maxHealth or 100, 1)
                local num12 = math.clamp(arg1.health / num10, 0, 1)
                local num13 = math.clamp(arg2_1.health / num11, 0, 1)
                local num14 = 0.5 * (1 - num8) + 0.5 * (1 - num12)
                local num15 = 0.5 * (1 - num9) + 0.5 * (1 - num13)
                if math.abs(num14 - num15) > 0.001 then return num14 < num15 end
                return arg1.dist > arg2_1.dist
            end)
        else
            table.sort(list11, function(arg1, arg2_1)
                if math.abs(arg1.dist - arg2_1.dist) > 0.01 then return arg1.dist < arg2_1.dist end
                return arg1.health < arg2_1.health
            end)
        end

        return list11[1]
    end

    function getClosestPlayerToMouse()
        local revolverAimbot = settings2.RevolverAimbot or {}
        local radius = revolverAimbot.Radius or 150
        local priority = revolverAimbot.Priority or "Nearest"
        local camera2 = workspace.CurrentCamera
        if not camera2 then return nil end

        local vector2 = lastIsMobile and camera2 and Vector2.new(camera2.ViewportSize.X / 2, camera2.ViewportSize.Y / 2)
            or UserInputService:GetMouseLocation()

        local team = localPlayer.Team
        local list11 = {}

        for _, player in ipairs(Players:GetPlayers()) do
            if player == localPlayer then continue end
            if team and player.Team == team then continue end
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")

            local humanoidRootPart2 = character and (character:FindFirstChild(revolverAimbot.TargetPart or "UpperTorso")
                or character:FindFirstChild("HumanoidRootPart"))

            if character and humanoid and humanoid.Health > 0 and humanoidRootPart2 then
                local point, v5 = camera2:WorldToViewportPoint(humanoidRootPart2.Position)

                if v5 then
                    local distance = (Vector2.new(point.X, point.Y) - vector2).Magnitude

                    if distance <= radius then
                        table.insert(list11, {
                            root = humanoidRootPart2,
                            dist = distance,
                            health = humanoid.Health,
                            maxHealth = math.max(humanoid.MaxHealth, 1),
                        })
                    end
                end
            end
        end

        local v5 = sortCandidatesByPriority(list11, priority, radius)
        return v5 and v5.root or nil
    end

    function updateFOVCircle()
        local showFOV = settings2.RevolverAimbot and settings2.RevolverAimbot.Enabled and settings2.RevolverAimbot.ShowFOV
        local radius = settings2.RevolverAimbot and settings2.RevolverAimbot.Radius or 150
        local camera2 = workspace.CurrentCamera
