    function runAimbot()
        local enabled = settings2.RevolverAimbot.Enabled

        if not enabled then
            updateFOVCircle()

            if lastIsMobile then
                updateMobileAimbotButton()
            end

            _G.VD_AimbotTarget = nil
            return
        end

        updateFOVCircle()

        if lastIsMobile then
            updateMobileAimbotButton()
        end

        local isMobileAimbotActive = false

        if lastIsMobile then
            isMobileAimbotActive = _G.VD_IsMobileAimbotActive
        else
            local key2 = settings2.RevolverAimbot.Key or "MouseButton2"

            if key2 == "MouseButton2" then
                isMobileAimbotActive = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
            elseif key2 == "MouseButton1" then
                isMobileAimbotActive = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
            else
                pcall(function()
                    isMobileAimbotActive = UserInputService:IsKeyDown(Enum.KeyCode[key2])
                end)
            end
        end

        if isMobileAimbotActive then
            if not _G.VD_AimbotTarget
                or not _G.VD_AimbotTarget.Parent
                or not _G.VD_AimbotTarget.Parent:FindFirstChildOfClass("Humanoid")
                or _G.VD_AimbotTarget.Parent:FindFirstChildOfClass("Humanoid").Health <= 0 then
                _G.VD_AimbotTarget = getClosestPlayerToMouse()
            end

            if _G.VD_AimbotTarget then
                local camera2 = workspace.CurrentCamera

                if camera2 then
                    local position = _G.VD_AimbotTarget.Position

                    if settings2.RevolverAimbot.PredictionEnabled then
                        local parent = _G.VD_AimbotTarget.Parent
                        local humanoidRootPart2 = parent and parent:FindFirstChild("HumanoidRootPart")

                        if humanoidRootPart2 then
                            local distance = (camera2.CFrame.Position - position).Magnitude
                            local bulletVelocity = settings2.RevolverAimbot.BulletVelocity or 800
                            local num8 = distance / bulletVelocity
                            local assemblyLinearVelocity = humanoidRootPart2.AssemblyLinearVelocity
                            position = position + assemblyLinearVelocity * num8
                        end
                    end

                    position = position + camera2.CFrame.RightVector * ((settings2.RevolverAimbot.OffsetX or 0) / 10) + camera2.CFrame.UpVector * ((settings2.RevolverAimbot.OffsetY or 0) / 10)

                    pcall(function()
                        local character = localPlayer.Character
                        local humanoidRootPart2 = character and character:FindFirstChild("HumanoidRootPart")

                        if humanoidRootPart2 then
                            local vector3 = Vector3.new(position.X, humanoidRootPart2.Position.Y, position.Z)
                            humanoidRootPart2.CFrame = CFrame.new(humanoidRootPart2.Position, vector3)
                        end
                    end)

                    local cFrame = CFrame.new(camera2.CFrame.Position, position)
                    local smoothness = settings2.RevolverAimbot.Smoothness or 0.15

                    if smoothness <= 0 then
                        camera2.CFrame = cFrame
                    else
                        camera2.CFrame = camera2.CFrame:Lerp(cFrame, smoothness)
                    end
                end
            end
        else
            _G.VD_AimbotTarget = nil
        end
    end

    RunService:BindToRenderStep("VD_Aimbot", Enum.RenderPriority.Camera.Value + 1, runAimbot)

    do
        local num8 = 0
        local flag15 = false
        local track = nil

        local function fnTeam()
            if localPlayer.Team then
                local str = localPlayer.Team.Name:lower()
                if str:find("killer") or str:find("slasher") or str:find("monster") then return false end
                if str:find("surv") then return true end
            end

            local role = localPlayer:GetAttribute("Role")
                or localPlayer.Character and localPlayer.Character:GetAttribute("Role")

            if role == "Killer"
                or localPlayer:GetAttribute("IsKiller") == true
                or localPlayer.Character and localPlayer.Character:GetAttribute("IsKiller") == true then
                return false
            end

            local character = localPlayer.Character

            if character and character.Parent then
                local str = character.Parent.Name:lower()
                if str:find("killer") then return false end
                if str:find("surv") then return true end
            end

            if role == "Survivor" then return true end

            if character then
                local str = character.Name:lower()

                if str:find("veil")
                    or str:find("myers")
                    or str:find("stalker")
                    or str:find("killer")
                    or str:find("abyss") then
                    return false
                end
            end

            return true
        end

        local function fnTool()
            if not fnTeam() then return nil end
            local character = localPlayer.Character

            if character then
                for _, child in ipairs(character:GetChildren()) do
                    if child:IsA("Tool") or child:IsA("Model") then
                        local str = child.Name:lower()

                        if str:find("twist")
                            or str:find("fate")
                            or str:find("revolver")
                            or str:find("gun")
                            or child:FindFirstChild("Right Arm")
                            or child:FindFirstChild("gun", true) then
                            return child
                        end
                    end
                end
            end

            local backpack = localPlayer:FindFirstChildOfClass("Backpack")

            if backpack then
                for _, child in ipairs(backpack:GetChildren()) do
                    if child:IsA("Tool") or child:IsA("Model") then
                        local str = child.Name:lower()

                        if str:find("twist")
                            or str:find("fate")
                            or str:find("revolver")
                            or str:find("gun")
                            or child:FindFirstChild("Right Arm")
                            or child:FindFirstChild("gun", true) then
                            return child
                        end
                    end
                end
            end

            return nil
        end

        local function fnLuaSourceContainer(instance2)
            if not instance2 then return nil end

            for _, descendant in ipairs(instance2:GetDescendants()) do
                if descendant:IsA("LuaSourceContainer")
                    and (descendant.Name:lower() == "gun" or descendant.Name:lower():find("twist")) then
                    if descendant.Parent
                        and descendant.Parent ~= instance2
                        and descendant.Parent.Name ~= "Right Arm" then
                        return descendant.Parent
                    end
                end
            end

            local instance3 = instance2:FindFirstChild("Right Arm")

            if instance3 then
                for _, child in ipairs(instance3:GetChildren()) do
                    if child:IsA("Model") then return child end
                end

                for _, child in ipairs(instance3:GetChildren()) do
                    if child:IsA("BasePart") and child.Name ~= "Right Arm" then return child end
                end
            end

            for _, child in ipairs(instance2:GetChildren()) do
                if child:IsA("Model") and child.Name ~= "Right Arm" then return child end
            end

            local gun = instance2:FindFirstChild("gun", true)

            if gun and not gun:IsA("LuaSourceContainer") then
                return gun
            elseif gun and gun:IsA("LuaSourceContainer") and gun.Parent then
                return gun.Parent
            end

            return instance2:FindFirstChildOfClass("BasePart") or instance2
        end

        local function fnFire()
            local replicatedStorage = game:GetService("ReplicatedStorage")
            local remotes = replicatedStorage:FindFirstChild("Remotes")
            local items = remotes and remotes:FindFirstChild("Items")

            if items then
                local revolver = items:FindFirstChild("Twist of Fate") or items:FindFirstChild("Revolver")
                local fire = revolver and revolver:FindFirstChild("Fire")
                if fire then return fire end

                for _, child in ipairs(items:GetChildren()) do
                    local str = child.Name:lower()

                    if str:find("twist") or str:find("fate") or str:find("revolver") then
                        local fire2 = child:FindFirstChild("Fire")
                        if fire2 then return fire2 end
                    end
                end
            end

            for _, descendant in ipairs(replicatedStorage:GetDescendants()) do
                if descendant.Name == "Fire" and descendant.Parent then
                    local str = descendant.Parent.Name:lower()

                    if str:find("twist") or str:find("fate") or str:find("revolver") then
                        return descendant
                    end
                end
            end

            return nil
        end

        local function fnAnimationId(instance2)
            pcall(function()
                local character = localPlayer.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")

                if humanoid then
                    local animation = Instance.new("Animation")
                    animation.AnimationId = "rbxassetid://124735239320776"
                    local track2 = humanoid:LoadAnimation(animation)
                    track2:Play()
                end

                if instance2 then
                    local shoot = instance2:FindFirstChild("shoot", true)

                    if shoot and shoot:IsA("Sound") then
                        shoot:Play()
                    end
                end
            end)
        end

        local function fnAnimationId2()
            pcall(function()
                local character = localPlayer.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")

                if humanoid and not track then
                    local animation = Instance.new("Animation")
                    animation.AnimationId = "rbxassetid://75029269564639"
