        local function fnRevolverSilentAim()
            if not (settings2.BypassToFRestrictions
                and isPremiumActive("BypassToFRestrictions")
                and map
                and map.BypassToFRestrictions) then
                return
            end

            if not fnTeam() then return end
            if not flag15 then return end
            local character = localPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return end
            local instance2_2 = fnTool()
            if not instance2_2 then return end
            local instance2_3 = fnLuaSourceContainer(instance2_2)
            if not instance2_3 then return end
            local now = tick()
            if now - num8 < 0.35 then return end
            num8 = now
            local remote = fnFire()
            if not remote then return end
            local camera2 = workspace.CurrentCamera
            local lookVector = camera2 and camera2.CFrame.LookVector or Vector3.new(0, 0, -1)

            if settings2.RevolverSilentAim and settings2.RevolverSilentAim.Enabled and isPremiumActive() then
                pcall(function()
                    local instance2 = nil
                    local huge = math.huge
                    local fovRadius = settings2.RevolverSilentAim.FOVRadius or 200
                    local vector2 = Vector2.new(camera2.ViewportSize.X / 2, camera2.ViewportSize.Y / 2)

                    for _, player in ipairs(Players:GetPlayers()) do
                        if player ~= localPlayer and player.Character then
                            local character2 = player.Character
                            local humanoid2 = character2:FindFirstChildOfClass("Humanoid")

                            local humanoidRootPart2 = character2:FindFirstChild("HumanoidRootPart")
                                or character2:FindFirstChild("UpperTorso")
                                or character2:FindFirstChild("Head")

                            if humanoid2 and humanoid2.Health > 0 and humanoidRootPart2 then
                                local flag16 = player:GetAttribute("Role") == "Killer"
                                    or player:GetAttribute("IsKiller") == true
                                    or character2:GetAttribute("Role") == "Killer"
                                    or character2:GetAttribute("IsKiller") == true

                                local target = settings2.RevolverSilentAim.Target or "Both Teams"
                                local flag17 = false

                                if target == "Both Teams" then
                                    flag17 = true
                                elseif target == "Killer" and flag16 then
                                    flag17 = true
                                elseif target == "Survivors" and not flag16 then
                                    flag17 = true
                                end

                                if flag17 then
                                    local vector3, v7 = camera2:WorldToViewportPoint(humanoidRootPart2.Position)

                                    if v7 or vector3.Z > 0 then
                                        local distance = (Vector2.new(vector3.X, vector3.Y) - vector2).Magnitude

                                        if distance <= fovRadius and distance < huge then
                                            huge = distance
                                            instance2 = character2
                                        end
                                    end
                                end
                            end
                        end
                    end

                    if instance2 then
                        local head = instance2:FindFirstChild("Head")
                            or instance2:FindFirstChild("UpperTorso")
                            or instance2:FindFirstChild("HumanoidRootPart")

                        if head then
                            local position = camera2.CFrame.Position
                            lookVector = (head.Position - position).Unit
                        end
                    end
                end)
            end

            pcall(function()
                local v7 = (vector and vector.create or Vector3.new)(lookVector.X, lookVector.Y, lookVector.Z)
                remote:FireServer(instance2_3, v7)
                fnAnimationId(instance2_3)
            end)
        end

        local screenGui2 = nil
        local textButton3 = nil
        local textButton4 = nil
        local instance2 = nil
        local flag16 = false

        local function fnUserInputType()
            if not lastIsMobile then return false end
            local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
            if not playerGui then return false end
            local survivorMob = playerGui:FindFirstChild("Survivor-mob") or playerGui:FindFirstChild("SurvivorMob")

            if not survivorMob then
                for _, child in ipairs(playerGui:GetChildren()) do
