                                if cancelaim and cancelaim.Visible then
                                    local absolutePosition = cancelaim.AbsolutePosition
                                    local absoluteSize = cancelaim.AbsoluteSize
                                    local v6, v7 = input.Position.X, input.Position.Y

                                    if v6 >= absolutePosition.X
