    function getSmoothedVelocity(player, offset, part)
        local object5Item = object5[player]
        local now = tick()
        local offset2 = offset

        if part and typeof(part) == "Instance" and part:IsA("BasePart") then
            if object5Item
                and object5Item.lastPos
                and now - object5Item.time > 0.001
                and now - object5Item.time < 0.5 then
                local num8 = now - object5Item.time
                offset2 = (part.Position - object5Item.lastPos) / num8
            end
        end

        if offset.Magnitude < 0.5 and offset2.Magnitude < 0.5 then
            if not object5Item then
                object5Item = {}
                object5[player] = object5Item
            end

            object5Item.velocity = Vector3.new(0, 0, 0)
            object5Item.time = now
            object5Item.lastPos = part and typeof(part) == "Instance" and part:IsA("BasePart") and part.Position or nil
            return Vector3.new(0, 0, 0)
        end

        if offset2.Magnitude > 60 then
            offset2 = offset
        end

        if offset.Magnitude > 60 then
            offset = offset2.Magnitude <= 60 and offset2 or Vector3.new(0, 0, 0)
        end

        local lerped = offset:Lerp(offset2, 0.5)

        if lerped.Magnitude > 40 then
