        if object5Item.velocity and object5Item.velocity.Magnitude > 1.5 and lerped.Magnitude > 1.5 then
            local dot = object5Item.velocity.Unit:Dot(lerped.Unit)

            if dot < 0.25 then
                object5Item.velocity = lerped
                object5Item.time = now
                object5Item.lastPos = part and typeof(part) == "Instance" and part:IsA("BasePart") and part.Position or nil
                return lerped
            end
        end

        local num8 = 0.45
        local lerped2 = object5Item.velocity:Lerp(lerped, num8)

        if lerped2.Magnitude < 0.2 then
            lerped2 = Vector3.new(0, 0, 0)
        elseif lerped2.Magnitude > 32 then
            lerped2 = lerped2.Unit * 32
        end

        object5Item.velocity = lerped2
        object5Item.time = now
        object5Item.lastPos = part and typeof(part) == "Instance" and part:IsA("BasePart") and part.Position or nil
        return lerped2
    end

    local function fnClamp()
        local success2, result2 = pcall(function()
            return num and num * 2 or 0.07
        end)

        if success2 and type(result2) == "number" and result2 > 0 then
            return math.clamp(result2 * 0.5, 0, 0.25)
        end

        return 0.035
    end

    function solveProjectileAim(arg1, arg2, arg3, arg4, arg5, arg6)
        local flag15 = arg5 and arg5 > 50 and arg5 or 150
        local flag16 = arg6 and arg6 > 0 and arg6 or 98
        local zero = arg3 or Vector3.zero
        local vector3 = Vector3.new(zero.X, 0, zero.Z)
        local num8 = math.clamp(zero.Y, -4, 1.5)
        local vector3_2 = Vector3.new(vector3.X, num8, vector3.Z)
        local v5 = fnClamp()
        local distance = (arg2 - arg1).Magnitude
        local num9 = distance / flag15
        local num10 = arg2

        for _ = 1, 4, 1 do
            local num11 = num9 + v5
            local offset = vector3_2 * num11
            local num12 = 32 * num11

            if offset.Magnitude > num12 then
                offset = offset.Unit * num12
            end

            num10 = arg2 + offset + 0.5 * (arg4 or Vector3.zero) * num11 ^ 2
            local vector2 = num10 - arg1
            local distance2 = Vector3.new(vector2.X, 0, vector2.Z).Magnitude
            local v6 = vector2.Y

            if flag16 == 0 then
                num9 = vector2.Magnitude / flag15
            else
                local num13 = 0.25 * flag16 ^ 2
                local num14 = v6 * flag16 - flag15 ^ 2
                local num15 = distance2 ^ 2 + v6 ^ 2
                local num16 = num14 ^ 2 - 4 * num13 * num15

                if num16 >= 0 then
                    local a = (-num14 - math.sqrt(num16)) / (2 * num13)
                    local b = (-num14 + math.sqrt(num16)) / (2 * num13)
                    local num17 = -1

                    if a > 0 and b > 0 then
                        num17 = math.min(a, b)
                    elseif a > 0 then
                        num17 = a
                    elseif b > 0 then
                        num17 = b
                    end

                    if num17 > 0 then
                        num9 = math.sqrt(num17)
                    else
                        num9 = vector2.Magnitude / flag15
                    end
                else
                    num9 = vector2.Magnitude / flag15
                    break
                end
            end
        end

        local num11 = num10 - arg1
        local vector3_3 = Vector3.new(0, -flag16, 0)
        local offset = (num11 - 0.5 * vector3_3 * num9 ^ 2) / num9
        return offset.Unit, num10
    end

