            textButton3.MouseButton1Click:Connect(function()
                TweenService:Create(
                    frame4,
                    TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
                    {Size = UDim2.new(0, 0, 0, 0)}
                ):Play()

                task.wait(0.25)
                frame4:Destroy()

                if callback6 then
                    callback6()
                else
                    mainFrame.Visible = true
                end
            end)

            TweenService:Create(
                frame4,
                TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                {Size = UDim2.new(0, 360, 0, 250)}
            ):Play()
        end

        function createChangelogPopup(callback6)
            local function fn9(change)
                local str7 = change:sub(1, 3)

                if str7 == "[+]" then
                    return "<font color=\"#72DC82\">[+]</font>" .. change:sub(4)
                elseif str7 == "[/]" then
                    return "<font color=\"#FFDC00\">[/]</font>" .. change:sub(4)
                elseif str7 == "[-]" then
                    return "<font color=\"#FF5F73\">[-]</font>" .. change:sub(4)
                else
                    return change
                end
            end

