    local function fnHuge(instance3)
        local huge, huge2 = math.huge, math.huge
        local huge3, huge4 = -math.huge, -math.huge
        local flag15 = false

        for _, child in ipairs(instance3:GetChildren()) do
            if child:IsA("GuiObject") and child.Name:find("^Survivor%d+$") and child.Visible then
                flag15 = true
                local point = child.AbsolutePosition - instance3.AbsolutePosition
                local absoluteSize = child.AbsoluteSize
                local v5 = point.X
                local v6 = point.Y
                local v7 = absoluteSize.X
                local v8 = absoluteSize.Y

                if v5 < huge then
                    huge = v5
                end

                if v6 < huge2 then
                    huge2 = v6
                end

                if v5 + v7 > huge3 then
                    huge3 = v5 + v7
                end

                if v6 + v8 > huge4 then
                    huge4 = v6 + v8
                end
            end
        end

        if flag15 and huge3 > huge and huge4 > huge2 then
            return UDim2.new(0, huge, 0, huge2), UDim2.new(0, huge3 - huge, 0, huge4 - huge2)
        end

        return nil, nil
    end

