    local function fnMagnitude(arg1)
        if not activeLoop then return end

        pcall(function()
            local camera2 = workspace.CurrentCamera
            if not camera2 or camera2.CameraType == Enum.CameraType.Scriptable then return end
            local replicatedStorage = game:GetService("ReplicatedStorage")

            if replicatedStorage:GetAttribute("RankedState") == "Intro"
                or replicatedStorage:GetAttribute("Darkness2Covered") == true then
                return
            end

            local cameraStiffnessEnabled = settings2.CameraStiffnessEnabled
            local cameraStiffness = cameraStiffnessEnabled and settings2.CameraStiffness or 1

            if cameraStiffnessEnabled
                and cameraStiffness
                and type(cameraStiffness) == "number"
                and cameraStiffness < 0.999
                and cameraStiffness > 0 then
                local position = camera2.CFrame.Position
                local num8 = camera2.CFrame - position

                if v5 then
                    if (position - v5).Magnitude > 20 then
                        v5 = position
                    end

                    local num9 = math.clamp(arg1 or 0.016666666666667, 0.001, 0.1)
                    local num10 = math.clamp(cameraStiffness, 0.005, 1) * 45
                    local num11 = math.clamp(1 - math.exp(-num10 * num9), 0.001, 1)
                    local lerped = v5:Lerp(position, num11)
                    camera2.CFrame = CFrame.new(lerped) * num8
                    v5 = lerped
                else
                    v5 = position
                end
            else
                v5 = camera2.CFrame.Position
            end

            local aspectRatioEnabled = settings2.AspectRatioEnabled
            local aspectRatio = aspectRatioEnabled and (settings2.AspectRatio or 0.65) or 1
            local aspectRatio2 = aspectRatio

            if aspectRatioEnabled and aspectRatio2 > 1.05 and aspectRatio2 <= 2.5 then
                aspectRatio2 = aspectRatio2 / 1.7777777777778
            end

            local flag15 = aspectRatioEnabled and math.abs(aspectRatio2 - 1) > 0.005
            local flag16 = settings2.FOV and settings2.FOV > 120

            if not flag15 and not flag16 then
                if camera2.FieldOfView ~= settings2.FOV then
                    camera2.FieldOfView = settings2.FOV
                end

                local cFrame = camera2.CFrame
                if cFrame.X ~= cFrame.X or cFrame.Y ~= cFrame.Y or cFrame.Z ~= cFrame.Z then return end
                local rightVector = cFrame.RightVector
                local upVector = cFrame.UpVector
                if rightVector.Magnitude < 0.01 or upVector.Magnitude < 0.01 then return end

                if math.abs(rightVector.Magnitude - 1) > 0.001 or math.abs(upVector.Magnitude - 1) > 0.001 then
                    camera2.CFrame = CFrame.fromMatrix(cFrame.Position, rightVector.Unit, upVector.Unit)
                end

                return
            end

            local num8 = 1
            local num9 = flag15 and math.clamp(aspectRatio2, 0.05, 3) or 1
            local num10 = math.min(settings2.FOV, 120)

            if camera2.FieldOfView ~= num10 then
                camera2.FieldOfView = num10
            end

            if flag16 then
                local v6 = math.rad(settings2.FOV / 2)
                local v7 = math.rad(num10 / 2)
                local num11 = math.tan(v7) / math.tan(v6)
                num8 = num8 * num11
                num9 = num9 * num11
            end

            local cFrame = camera2.CFrame
            if cFrame.X ~= cFrame.X or cFrame.Y ~= cFrame.Y or cFrame.Z ~= cFrame.Z then return end
            local rightVector = cFrame.RightVector
            local upVector = cFrame.UpVector
            if rightVector.Magnitude < 0.01 or upVector.Magnitude < 0.01 then return end
            local v6 = CFrame.fromMatrix(cFrame.Position, rightVector.Unit, upVector.Unit)
            if num8 ~= num8 or num9 ~= num9 or num8 <= 0 or num9 <= 0 then return end
            camera2.CFrame = v6 * CFrame.new(0, 0, 0, num8, 0, 0, 0, num9, 0, 0, 0, 1)
        end)
    end

